/* Ngữ pháp B1 · Intermediate — sinh tự động bởi tools/build-grammar.py (npm run build:grammar), đừng sửa tay */
(window.FA_GRAMMAR_LESSONS = window.FA_GRAMMAR_LESSONS || {})["B1"] = [{"n":1,"title":"Both, either, neither & all of","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhóm từ hạn định này cho biết người nói đang nói về bao nhiêu đối tượng trong một tập hợp. Có hai trục cần nắm: số lượng đối tượng trong tập hợp và số của động từ theo sau. Both luôn kéo theo động từ số nhiều, còn either, neither và each kéo theo động từ số ít dù chúng nói về hai hoặc nhiều đối tượng."},{"p":"Cấu trúc chính: both + danh từ số nhiều | either/neither + danh từ số ít | all/most/none of + the + danh từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Both options are good, but neither is cheap. (Nói về cả hai | Nói về một trong hai | Phủ định cả hai)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nói về cả hai: Both đi với danh từ số nhiều và động từ số nhiều. (Both rooms are free.)"},{"p":"Nói về một trong hai: Either nghĩa là cái nào cũng được; đi với danh từ số ít. (You can take either bus.)"},{"p":"Phủ định cả hai: Neither nghĩa là không cái nào; đã mang nghĩa phủ định nên động từ ở dạng khẳng định. (Neither answer is correct.)"},{"p":"Nói về một nhóm lớn hơn: All, most, some, none, each of cộng the hoặc từ sở hữu rồi danh từ. (Most of the students passed.)"},{"p":"Ghi nhớ: Both, either, neither dùng cho hai đối tượng; all, most, none, each dùng cho nhóm từ ba đối tượng trở lên."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: both + danh từ số nhiều | either/neither + danh từ số ít | all/most/none of + the + danh từ"},{"table":[["Nhóm cấu trúc","Công thức","Ví dụ"],["Hai đối tượng","both + danh từ số nhiều | either/neither + danh từ số ít","both books, either book, neither book"],["Có of","both/either/neither of + the/my/these + danh từ số nhiều","neither of the answers"],["Nhóm lớn hơn","all/most/some/none/each of + the + danh từ","none of the files"],["Cặp liên từ","both … and | either … or | neither … nor","either tea or coffee"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đếm số đối tượng trong tập hợp: Hai đối tượng thì dùng both, either, neither; ba trở lên thì dùng all, most, none, each. (neither of the two ↔ none of the five)"},{"p":"02. Chọn số của danh từ theo sau: Both đi với danh từ số nhiều; either và neither đi với danh từ số ít, nhưng khi có of thì danh từ ở số nhiều. (either book ↔ either of the books)"},{"p":"03. Chọn số của động từ: Both kéo theo động từ số nhiều; either, neither, each và none thường kéo theo động từ số ít. (Both are ready. / Neither is ready.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Both và neither","Both options are good, but neither is cheap.\n(Cả hai lựa chọn đều tốt, nhưng không lựa chọn nào rẻ.)","Both đi với động từ số nhiều are, còn neither đi với động từ số ít is."],["Either với danh từ số ít","You can take either bus; they both go to the centre.\n(Bạn bắt xe nào cũng được, cả hai đều đi vào trung tâm.)","Either đi với danh từ số ít bus, còn both trong vế sau đi với động từ số nhiều."],["Có of","Neither of the answers was correct.\n(Không câu trả lời nào đúng.)","Khi có of, danh từ ở số nhiều nhưng động từ vẫn ở số ít trong văn phong chuẩn mực."],["Nhóm lớn hơn","Most of the students passed, but none of them got full marks.\n(Phần lớn sinh viên đỗ, nhưng không ai đạt điểm tối đa.)","Most of và none of dùng cho nhóm từ ba đối tượng trở lên."],["Each","Each candidate has fifteen minutes to present.\n(Mỗi thí sinh có mười lăm phút để trình bày.)","Each nhấn vào từng cá thể một nên đi với danh từ và động từ số ít."],["Cặp liên từ","We can meet either on Friday or on Saturday, but neither Monday nor Tuesday works for me.\n(Chúng ta gặp vào thứ Sáu hoặc thứ Bảy đều được, nhưng cả thứ Hai và thứ Ba đều không ổn với tôi.)","Cặp either … or và neither … nor nối hai lựa chọn song song."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai đối tượng và nhiều đối tượng"},{"table":[["Từ hạn định","Cách dùng","Ví dụ"],["both","cả hai, động từ số nhiều","Both are open."],["either","một trong hai, động từ số ít","Either is fine."],["neither","không cái nào trong hai, động từ số ít","Neither is open."],["all / most / none","nhóm từ ba trở lên","None of the five are open."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Both option are good. → Đã sửa: Both options are good. — Both đi với danh từ số nhiều."},{"p":"Chưa đúng: Neither of the answers were correct. → Đã sửa: Neither of the answers was correct. — Neither kéo theo động từ số ít trong văn phong chuẩn mực."},{"p":"Chưa đúng: None of the two files opened. → Đã sửa: Neither of the two files opened. — Với đúng hai đối tượng thì dùng neither, none dùng cho nhóm từ ba trở lên."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Tập hợp có hai đối tượng hay nhiều hơn."},{"p":"Danh từ theo sau ở số ít hay số nhiều cho đúng từ hạn định."},{"p":"Động từ hòa hợp đúng với từ hạn định."},{"p":"Neither và none không dùng kèm not."}]}],"id":"b1-01"},{"n":2,"title":"Past continuous","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Quá khứ tiếp diễn dựng nên bối cảnh: một hành động đang kéo dài tại một thời điểm trong quá khứ. Nó thường đi cặp với quá khứ đơn, trong đó quá khứ tiếp diễn là hành động dài còn quá khứ đơn là hành động ngắn xen vào. Hai liên từ chi phối cặp thì này là when và while."},{"p":"Cấu trúc chính: was/were + V-ing | when + quá khứ đơn"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I was cooking when the phone rang. (Hành động đang diễn ra tại mốc quá khứ | Hành động dài bị hành động ngắn xen vào | Hai hành động song song)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Hành động đang diễn ra tại mốc quá khứ: Thường nêu rõ giờ hoặc thời điểm. (At eight o'clock I was having dinner.)"},{"p":"Hành động dài bị hành động ngắn xen vào: Hành động dài dùng quá khứ tiếp diễn, hành động xen vào dùng quá khứ đơn. (I was cooking when the phone rang.)"},{"p":"Hai hành động song song: Cả hai đều kéo dài, nối bằng while. (She was reading while he was cooking.)"},{"p":"Dựng bối cảnh cho câu chuyện: Mở đầu bằng quá khứ tiếp diễn rồi chuyển sang quá khứ đơn để kể diễn biến. (It was raining hard. Suddenly the lights went out.)"},{"p":"Ghi nhớ: Diễn tả hành động đang diễn ra tại một thời điểm trong quá khứ, thường bị một hành động khác xen vào."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: was/were + V-ing | when + quá khứ đơn"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Khẳng định","I/he/she/it + was + V-ing | you/we/they + were + V-ing","They were waiting."],["Phủ định","wasn't / weren't + V-ing","He wasn't listening."],["Nghi vấn","Was/Were + S + V-ing?","Were you sleeping?"],["Cặp liên từ","when + quá khứ đơn | while + quá khứ tiếp diễn","While I was walking, I met her."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt hành động dài và ngắn: Hành động dài làm bối cảnh dùng quá khứ tiếp diễn; hành động ngắn xen vào dùng quá khứ đơn. (was cooking (dài) - rang (ngắn))"},{"p":"02. Chọn was hay were theo chủ ngữ: I, he, she, it dùng was; you, we, they dùng were. (The children were playing.)"},{"p":"03. Gắn liên từ đúng vế: When thường đi với quá khứ đơn, while thường đi với quá khứ tiếp diễn. (when the phone rang / while I was cooking)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Hành động xen vào","I was cooking when the phone rang.\n(Tôi đang nấu ăn thì điện thoại reo.)","Nấu ăn là hành động dài, điện thoại reo là hành động ngắn xen vào giữa."],["Mốc thời gian cụ thể","At eight o'clock last night we were having dinner.\n(Tám giờ tối qua chúng tôi đang ăn cơm.)","Mốc giờ cho biết hành động đang ở giữa tiến trình tại thời điểm đó."],["Hai hành động song song","She was reading while her brother was playing the guitar.\n(Cô ấy đang đọc sách còn anh trai đang chơi ghi ta.)","Cả hai đều kéo dài nên cả hai dùng quá khứ tiếp diễn, nối bằng while."],["Dựng bối cảnh","It was raining hard and the wind was blowing when we arrived.\n(Trời đang mưa to và gió đang thổi mạnh khi chúng tôi đến.)","Hai mệnh đề tiếp diễn dựng bối cảnh, mệnh đề quá khứ đơn nêu sự việc chính."],["Phủ định","I wasn't listening because I was thinking about something else.\n(Tôi không nghe vì đang nghĩ chuyện khác.)","Not đặt giữa was và V-ing."],["Nghi vấn","What were you doing at ten o'clock yesterday?\n(Mười giờ hôm qua bạn đang làm gì?)","Từ hỏi đứng đầu, rồi đến were, chủ ngữ và V- ing."],["Hành động cắt ngang","While I was walking home, I saw an old friend.\n(Đang đi bộ về nhà thì tôi gặp một người bạn cũ.)","Nền kéo dài ở quá khứ tiếp diễn (was walking); hành động cắt ngang dùng quá khứ đơn - see là động từ bất quy tắc nên thành saw."],["Tiếng động xen vào","I was walking to school when I heard a strange noise.\n(Tôi đang đi tới trường thì nghe một tiếng động lạ.)","Hành động ngắn xen vào dùng quá khứ đơn, cũng là dạng bất quy tắc: hear → heard."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Quá khứ đơn và quá khứ tiếp diễn"},{"table":[["Cấu trúc","Chức năng","Ví dụ"],["when + quá khứ đơn","hành động ngắn xen vào","when the bell rang"],["while + quá khứ tiếp diễn","hành động dài làm bối cảnh","while we were studying"],["cả hai quá khứ đơn","hai việc xảy ra lần lượt","When she arrived, we left."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I cooked when the phone was ringing. → Đã sửa: I was cooking when the phone rang. — Hành động dài phải ở quá khứ tiếp diễn, hành động ngắn xen vào ở quá khứ đơn."},{"p":"Chưa đúng: They was playing football. → Đã sửa: They were playing football. — Chủ ngữ số nhiều they dùng were."},{"p":"Chưa đúng: While I was walking, I was meeting an old friend. → Đã sửa: While I was walking, I met an old friend. — Gặp bạn là việc xảy ra trong khoảnh khắc nên dùng quá khứ đơn."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Hành động nào là bối cảnh dài, hành động nào là sự việc ngắn."},{"p":"Was và were chọn đúng theo chủ ngữ."},{"p":"Liên từ when và while gắn đúng vế."},{"p":"Động từ chính ở dạng V-ing trong mệnh đề tiếp diễn."}]}],"id":"b1-02"},{"n":3,"title":"Present perfect vs past simple","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Hai thì này cùng nói về việc đã xảy ra, nhưng khác nhau ở chỗ người nói đặt sự việc ở đâu. Quá khứ đơn neo sự việc vào một mốc đã đóng lại. Hiện tại hoàn thành để sự việc lơ lửng, không nêu thời điểm, vì điều đáng nói là kết quả hoặc kinh nghiệm tính đến hiện tại. Trong hội thoại thực tế, người ta thường mở đầu bằng hiện tại hoàn thành rồi chuyển sang quá khứ đơn để kể chi tiết."},{"p":"Cấu trúc chính: have/has + V3 | V2/V-ed + mốc thời gian đã qua"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I have finished the report, so I sent it this morning. (Nêu tin mới rồi kể chi tiết | Khoảng thời gian đã đóng hoặc còn mở | Trải nghiệm so với sự việc cụ thể)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu tin mới rồi kể chi tiết: Câu đầu dùng hiện tại hoàn thành để thông báo, các câu sau dùng quá khứ đơn để nêu thời gian và diễn biến. (I've lost my wallet. I left it on the bus.)"},{"p":"Khoảng thời gian đã đóng hoặc còn mở: This morning khi buổi sáng đã qua thì dùng quá khứ đơn; today khi ngày còn đang diễn ra thì dùng hiện tại hoàn thành. (I have called him twice today.)"},{"p":"Trải nghiệm so với sự việc cụ thể: Hiện tại hoàn thành cho câu hỏi đã từng chưa; quá khứ đơn cho câu hỏi khi nào. (Have you been to Hue? — Yes, I went there in 2022.)"},{"p":"Kết quả còn hiện hữu: Hiện tại hoàn thành nhấn mạnh hậu quả vẫn đang tồn tại. (She has broken her leg, so she can't walk.)"},{"p":"Ghi nhớ: Có mốc thời gian đã kết thúc thì dùng quá khứ đơn; không nêu thời điểm và quan tâm kết quả thì dùng hiện tại hoàn thành."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: have/has + V3 | V2/V-ed + mốc thời gian đã qua"},{"table":[["Nhóm cấu trúc","Công thức / Dấu hiệu","Ví dụ"],["Hiện tại hoàn thành","have/has + V3, không có mốc đã kết thúc","I have read that book."],["Quá khứ đơn","V2/V-ed + mốc thời gian đã qua","I read it last year."],["Dấu hiệu hiện tại hoàn thành","ever, never, just, already, yet, so far, recently, this week","She has just left."],["Dấu hiệu quá khứ đơn","yesterday, last …, ago, in 2020, when I was …","She left ten minutes ago."],["Bất quy tắc trong quá khứ đơn","meet → met, fall → fell, see → saw (mốc thời gian xác định thì dùng dạng quá khứ đơn này)","I met her at the conference last week. / Output fell sharply in 2008."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Tìm cụm chỉ thời gian trong câu: Nếu cụm đó chỉ một khoảng đã đóng lại thì bắt buộc dùng quá khứ đơn. (last night → quá khứ đơn)"},{"p":"02. Xét khoảng thời gian còn mở hay đã đóng: Today, this week, this year vẫn đang mở nên đi được với hiện tại hoàn thành. (I have seen him twice this week.)"},{"p":"03. Xét trọng tâm thông tin: Nếu điều quan trọng là kết quả hiện tại thì dùng hiện tại hoàn thành; nếu là diễn biến đã qua thì dùng quá khứ đơn. (I've broken it. ↔ I broke it yesterday.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Tin mới rồi chi tiết","I have lost my wallet. I left it on the bus this morning.\n(Tôi mất ví rồi. Sáng nay tôi để quên trên xe buýt.)","Câu đầu thông báo kết quả nên dùng hiện tại hoàn thành; câu sau có mốc this morning nên dùng quá khứ đơn."],["Khoảng còn mở","I have called him twice today.\n(Hôm nay tôi gọi cho anh ấy hai lần.)","Today chưa kết thúc nên số lần còn có thể tăng, vì vậy dùng hiện tại hoàn thành."],["Khoảng đã đóng","I called him twice yesterday.\n(Hôm qua tôi gọi cho anh ấy hai lần.)","Yesterday đã đóng lại nên con số là cố định và thì phải là quá khứ đơn."],["Trải nghiệm rồi chi tiết","Have you ever been to Hue? — Yes, I went there in 2022.\n(Bạn từng đến Huế chưa? — Rồi, tôi đi năm 2022.)","Câu hỏi về trải nghiệm dùng hiện tại hoàn thành; câu trả lời có năm cụ thể nên chuyển sang quá khứ đơn."],["Kết quả hiện hữu","She has broken her leg, so she can't play this season.\n(Cô ấy bị gãy chân nên mùa này không chơi được.)","Việc gãy chân thuộc quá khứ nhưng hậu quả vẫn tác động đến hiện tại."],["Dấu hiệu ago","He graduated three years ago and has worked here since then.\n(Anh ấy tốt nghiệp ba năm trước và làm ở đây từ đó đến nay.)","Ago xác định mốc quá khứ nên không dùng với hiện tại hoàn thành (thường đi với quá khứ đơn, hoặc quá khứ tiếp diễn); since then đi với hiện tại hoàn thành."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Cùng một việc, hai cách nhìn"},{"table":[["Câu ví dụ","Cách nhìn","Hàm ý"],["I have lost my keys.","vẫn chưa tìm được, kết quả còn đó","nên không vào nhà được"],["I lost my keys yesterday.","kể lại sự việc đã qua","có thể đã tìm lại được rồi"],["Have you finished?","hỏi về trạng thái hiện tại","công việc còn đang dở"],["Did you finish on time?","hỏi về sự việc đã kết thúc","nói về buổi làm hôm qua"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I have finished the report this morning. → Đã sửa: I finished the report this morning. — Khi buổi sáng đã qua, this morning là mốc đã kết thúc nên dùng quá khứ đơn."},{"p":"Chưa đúng: She has left the office ten minutes ago. → Đã sửa: She left the office ten minutes ago. — Ago xác định thời điểm trước hiện tại nên không dùng với hiện tại hoàn thành; thường đi với quá khứ đơn (và có thể đi với quá khứ tiếp diễn, vd: I was working here two years ago)."},{"p":"Chưa đúng: Did you ever go to Japan? → Đã sửa: Have you ever been to Japan? — Câu hỏi về trải nghiệm không nêu thời điểm nên dùng hiện tại hoàn thành."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu có cụm chỉ thời gian đã kết thúc hay không."},{"p":"Khoảng thời gian được nêu còn đang diễn ra hay đã đóng lại."},{"p":"Trọng tâm là kết quả hiện tại hay diễn biến đã qua."},{"p":"Dạng động từ là quá khứ phân từ hay quá khứ đơn cho đúng thì."}]}],"id":"b1-03"},{"n":4,"title":"For, since, just, already & yet","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhóm từ này là hệ thống dấu hiệu đi kèm hiện tại hoàn thành. For và since trả lời câu hỏi bao lâu: for đo độ dài khoảng thời gian, since đánh dấu điểm bắt đầu. Just, already và yet cho biết sự việc đang ở đâu so với mong đợi của người nói, và mỗi từ có vị trí riêng trong câu."},{"p":"Cấu trúc chính: for + khoảng thời gian | since + mốc thời gian"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She has lived here for ten years. (Đo độ dài khoảng thời gian | Đánh dấu điểm bắt đầu | Nói về việc vừa xảy ra)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Đo độ dài khoảng thời gian: For đi với một quãng: hai giờ, ba ngày, nhiều năm. (for two hours / for a long time)"},{"p":"Đánh dấu điểm bắt đầu: Since đi với một mốc: một năm, một ngày, một sự kiện. (since 2015 / since I was a child)"},{"p":"Nói về việc vừa xảy ra: Just đứng giữa trợ động từ và quá khứ phân từ. (She has just left.)"},{"p":"Việc sớm hơn hoặc muộn hơn mong đợi: Already dùng trong câu khẳng định, yet dùng trong câu phủ định và nghi vấn. (I have already eaten. / Have you eaten yet?)"},{"p":"Ghi nhớ: For đi với khoảng thời gian, since đi với mốc bắt đầu; just, already, yet cho biết tiến độ của sự việc."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: for + khoảng thời gian | since + mốc thời gian"},{"table":[["Dấu hiệu","Công thức / Vị trí","Ví dụ"],["for","for + khoảng thời gian","for three weeks"],["since","since + mốc thời gian hoặc mệnh đề quá khứ đơn","since last Monday, since she arrived"],["just / already","have/has + just/already + V3","He has already finished."],["yet","đứng cuối câu phủ định hoặc câu hỏi","They haven't arrived yet."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt quãng và mốc thời gian: Trả lời được bao lâu thì dùng for; trả lời được từ khi nào thì dùng since. (ten years → for / 2015 → since)"},{"p":"02. Đặt just và already vào giữa: Hai trạng từ này nằm giữa have/has và quá khứ phân từ. (has just arrived)"},{"p":"03. Đặt yet ở cuối câu: Already và yet không thay thế nhau được vì chúng thuộc hai thể câu khác nhau. (Have you finished yet?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Khoảng thời gian","She has lived here for ten years.\n(Cô ấy đã sống ở đây mười năm.)","Ten years là độ dài một quãng nên dùng for."],["Mốc bắt đầu","She has lived here since 2015.\n(Cô ấy sống ở đây từ năm 2015.)","2015 là một điểm trên trục thời gian nên dùng since."],["Since với mệnh đề","I haven't seen him since he moved to Hanoi.\n(Tôi không gặp anh ấy từ khi anh chuyển ra Hà Nội.)","Sau since có thể là một mệnh đề ở quá khứ đơn đánh dấu điểm bắt đầu."],["Just","The train has just left the station.\n(Tàu vừa rời ga.)","Just nằm giữa has và quá khứ phân từ, chỉ việc xảy ra cách đây rất ngắn."],["Already","I have already sent the email, so you don't need to.\n(Tôi gửi email rồi nên bạn không cần gửi nữa.)","Already trong câu khẳng định, hàm ý sớm hơn người nghe nghĩ."],["Yet","Have you finished your homework yet? — No, not yet.\n(Bạn làm xong bài tập chưa? — Chưa.)","Yet đứng cuối câu hỏi và câu phủ định, hàm ý việc được mong đợi sẽ xảy ra."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Phân biệt bốn dấu hiệu"},{"table":[["Từ dấu hiệu","Đặc điểm","Ví dụ"],["for","độ dài khoảng thời gian","for six months"],["since","điểm bắt đầu","since June"],["already","đã xảy ra, sớm hơn mong đợi, câu khẳng định","She has already gone."],["yet","chưa xảy ra, câu phủ định và nghi vấn","She hasn't gone yet."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She has lived here since ten years. → Đã sửa: She has lived here for ten years. — Ten years là một quãng nên phải dùng for."},{"p":"Chưa đúng: I have already not eaten. → Đã sửa: I haven't eaten yet. — Câu phủ định dùng yet ở cuối câu, không dùng already."},{"p":"Chưa đúng: He has finished just his work. → Đã sửa: He has just finished his work. — Just đứng trước quá khứ phân từ, không đứng sau nó."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Thông tin thời gian là một quãng hay một mốc."},{"p":"Just và already đặt giữa trợ động từ và quá khứ phân từ."},{"p":"Yet đặt cuối câu và chỉ trong câu phủ định hoặc nghi vấn."},{"p":"Thì của động từ là hiện tại hoàn thành cho các dấu hiệu này."}]}],"id":"b1-04"},{"n":5,"title":"Present perfect continuous","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Hiện tại hoàn thành tiếp diễn nhấn mạnh thời lượng và quá trình của một hành động bắt đầu trong quá khứ và còn liên quan đến hiện tại. So với hiện tại hoàn thành, thì này quan tâm đến việc đã làm bao lâu hơn là đã làm xong bao nhiêu. Nó cũng dùng để giải thích một dấu hiệu đang thấy trước mắt."},{"p":"Cấu trúc chính: S + have/has been + V-ing"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I have been waiting for an hour. (Nhấn mạnh thời lượng | Hành động vừa dừng, để lại dấu vết | Việc lặp lại trong một khoảng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhấn mạnh thời lượng: Đi với for, since, all day, all morning. (I have been studying since seven.)"},{"p":"Hành động vừa dừng, để lại dấu vết: Dùng để giải thích tình trạng đang quan sát được. (Your eyes are red. Have you been crying?)"},{"p":"Việc lặp lại trong một khoảng: Nhấn mạnh tính liên tục của chuỗi hành động. (She has been calling me all week.)"},{"p":"Hành động chưa hoàn tất: Khác với hiện tại hoàn thành, thì này không hàm ý đã xong. (I have been reading this book. (chưa đọc hết))"},{"p":"Ghi nhớ: Nhấn mạnh quá trình kéo dài từ quá khứ đến hiện tại, thường kèm for hoặc since."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + have/has been + V-ing"},{"table":[["Dạng thức","Công thức / Quy tắc","Ví dụ"],["Khẳng định","S + have/has been + V-ing","They have been working."],["Phủ định","haven't / hasn't been + V-ing","He hasn't been sleeping well."],["Nghi vấn","Have/Has + S + been + V-ing?","How long have you been learning English?"],["Động từ không dùng","know, believe, own, belong - dùng hiện tại hoàn thành thay thế","I have known her for years."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Giữ nguyên thành phần been: Cấu trúc gồm ba phần: have/has, been và V-ing; thiếu been là lỗi phổ biến. (has been running)"},{"p":"02. Chọn have hay has theo chủ ngữ: Chỉ phần have/has biến đổi, been và V-ing giữ nguyên. (She has been… / They have been…)"},{"p":"03. Kiểm tra động từ chỉ trạng thái: Động từ chỉ trạng thái không dùng dạng tiếp diễn nên phải chuyển sang hiện tại hoàn thành. (I have had this bike for years.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nhấn mạnh thời lượng","I have been waiting for an hour.\n(Tôi đã đợi suốt một tiếng.)","Trọng tâm là độ dài của việc đợi và việc đợi có thể vẫn đang tiếp tục."],["Giải thích dấu vết","Your hands are dirty. Have you been working in the garden?\n(Tay bạn bẩn này. Bạn vừa làm vườn à?)","Hành động vừa dừng nhưng dấu vết còn thấy được ở hiện tại."],["Với since","She has been studying since seven o'clock this morning.\n(Cô ấy học từ bảy giờ sáng nay.)","Since đánh dấu điểm bắt đầu và việc học vẫn đang tiếp diễn."],["Việc lặp lại","They have been calling me all week about the same problem.\n(Suốt tuần nay, họ gọi cho tôi về cùng một chuyện.)","All week cho thấy chuỗi hành động lặp lại liên tục trong một khoảng."],["Chưa hoàn tất","I have been reading this novel, but I am only halfway through.\n(Tôi đang đọc quyển tiểu thuyết này nhưng mới được nửa.)","Thì này không hàm ý đã xong, khác với I have read this novel."],["Câu hỏi về thời lượng","How long have you been learning English?\n(Bạn học tiếng Anh bao lâu rồi?)","How long là câu hỏi điển hình của thì này vì nó nhằm vào thời lượng."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai thì hiện tại hoàn thành"},{"table":[["Cấu trúc","Trọng tâm","Ví dụ"],["have/has + V3","nhấn mạnh kết quả, số lượng đã hoàn tất","I have written three emails."],["have/has been + V-ing","nhấn mạnh quá trình, thời lượng","I have been writing emails all morning."],["cả hai đều đúng","với động từ chỉ hoạt động kéo dài như live, work, study","I have lived / have been living here for years."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I am waiting for an hour. → Đã sửa: I have been waiting for an hour. — Hành động bắt đầu trong quá khứ và kéo dài đến hiện tại cần hiện tại hoàn thành tiếp diễn, không dùng hiện tại tiếp diễn."},{"p":"Chưa đúng: She has studying since seven. → Đã sửa: She has been studying since seven. — Thiếu been thì cấu trúc chưa hoàn chỉnh."},{"p":"Chưa đúng: I have been knowing her for years. → Đã sửa: I have known her for years. — Know là động từ chỉ trạng thái nên dùng hiện tại hoàn thành."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cấu trúc có đủ have/has, been và V-ing."},{"p":"Trọng tâm là thời lượng hay kết quả."},{"p":"Động từ không thuộc nhóm chỉ trạng thái."},{"p":"For hoặc since dùng đúng với quãng hoặc mốc thời gian."}]}],"id":"b1-05"},{"n":6,"title":"Past perfect","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi kể về quá khứ, người nói thường cần chỉ ra việc nào xảy ra trước việc nào. Quá khứ hoàn thành đánh dấu hành động xảy ra sớm hơn, còn quá khứ đơn đánh dấu mốc tham chiếu. Nếu trình tự đã rõ nhờ các liên từ như before hoặc after, có thể dùng quá khứ đơn cho cả hai mệnh đề."},{"p":"Cấu trúc chính: had + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The film had already started when we arrived. (Hành động xảy ra trước một mốc quá khứ | Nguyên nhân của một tình trạng quá khứ | Trong câu tường thuật)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Hành động xảy ra trước một mốc quá khứ: Mốc tham chiếu thường ở quá khứ đơn hoặc là một cụm chỉ thời gian. (By 2020 he had finished his degree.)"},{"p":"Nguyên nhân của một tình trạng quá khứ: Việc xảy ra trước là lí do của tình trạng được kể sau. (She was tired because she hadn't slept.)"},{"p":"Trong câu tường thuật: Khi lùi thì, hiện tại hoàn thành và quá khứ đơn đều chuyển thành quá khứ hoàn thành. (He said he had seen the film.)"},{"p":"Với các trạng từ chỉ trình tự: Already, just, never, by the time làm rõ quan hệ trước sau. (The train had just left when I got there.)"},{"p":"Ghi nhớ: Diễn tả hành động xảy ra trước một mốc hoặc một hành động khác trong quá khứ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: had + V3"},{"table":[["Dạng thức","Công thức / Dấu hiệu","Ví dụ"],["Khẳng định","S + had + V3 (dùng chung cho mọi chủ ngữ)","They had left."],["Phủ định","had not (hadn't) + V3","She hadn't eaten."],["Nghi vấn","Had + S + V3?","Had you met him before?"],["Liên từ thường gặp","by the time, before, after, when, already, just","By the time we arrived, the show had ended."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mốc tham chiếu trong quá khứ: Mốc này có thể là một giờ, một năm hoặc một hành động ở quá khứ đơn. (when we arrived)"},{"p":"02. Dùng quá khứ hoàn thành cho hành động trước: Had dùng chung cho mọi chủ ngữ nên không cần chia theo ngôi. (had already started)"},{"p":"03. Xét mức cần thiết của quá khứ hoàn thành: Khi before hoặc after đã làm rõ trình tự, quá khứ đơn cho cả hai mệnh đề là chấp nhận được. (She left before I arrived.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Trước một mốc","The film had already started when we arrived.\n(Phim đã chiếu được một lúc khi chúng tôi đến.)","Việc phim bắt đầu xảy ra trước mốc chúng tôi đến, nên dùng quá khứ hoàn thành."],["Giải thích nguyên nhân","She was exhausted because she hadn't slept the night before.\n(Cô ấy kiệt sức vì đêm trước không ngủ.)","Việc không ngủ xảy ra trước tình trạng kiệt sức được kể ở quá khứ đơn."],["By the time","By the time the ambulance arrived, the man had recovered.\n(Đến lúc xe cấp cứu tới thì người đàn ông đã hồi phục.)","By the time giới thiệu mốc tham chiếu, mệnh đề còn lại dùng quá khứ hoàn thành."],["Trong câu tường thuật","He said he had seen that film twice.\n(Anh ấy nói đã xem bộ phim đó hai lần.)","Lời gốc là I have seen, khi lùi thì trở thành had seen."],["Với just","The train had just left when I got to the platform.\n(Tàu vừa rời đi khi tôi ra tới sân ga.)","Just nằm giữa had và quá khứ phân từ."],["Không cần quá khứ hoàn thành","She left the office before I arrived.\n(Cô ấy rời cơ quan trước khi tôi đến.)","Before đã làm rõ trình tự nên hai mệnh đề dùng quá khứ đơn cũng tự nhiên."],["Phân từ bất quy tắc","When we got home, our parents had already gone to bed.\n(Khi chúng tôi về đến nhà, bố mẹ đã đi ngủ.)","Sau had luôn là quá khứ phân từ: go → gone, read → read, see → seen - không phải dạng quá khứ đơn went, saw."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba thì trên trục thời gian quá khứ"},{"table":[["Thì","Vị trí trên trục thời gian","Ví dụ"],["quá khứ hoàn thành","xảy ra trước mốc quá khứ","had finished"],["quá khứ đơn","mốc tham chiếu","arrived"],["quá khứ tiếp diễn","đang diễn ra tại mốc đó","was waiting"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The film already started when we arrived. → Đã sửa: The film had already started when we arrived. — Việc xảy ra trước mốc quá khứ cần quá khứ hoàn thành để làm rõ trình tự."},{"p":"Chưa đúng: She had ate before we came. → Đã sửa: She had eaten before we came. — Sau had phải là quá khứ phân từ, không phải quá khứ đơn."},{"p":"Chưa đúng: When I had arrived, everyone had left. → Đã sửa: When I arrived, everyone had left. — Mốc tham chiếu dùng quá khứ đơn, chỉ hành động xảy ra sớm hơn mới dùng quá khứ hoàn thành."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mốc tham chiếu trong quá khứ đã được xác định."},{"p":"Hành động xảy ra sớm hơn dùng had + quá khứ phân từ."},{"p":"Mốc tham chiếu giữ ở quá khứ đơn."},{"p":"Trình tự đã rõ nhờ liên từ thì không cần dùng quá khứ hoàn thành."},{"p":"Thì quá khứ hoàn thành tiếp diễn dùng had been cộng V-ing."}]}],"id":"b1-06"},{"n":7,"title":"Future continuous","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tương lai tiếp diễn đặt người nghe vào một thời điểm trong tương lai và cho thấy hành động lúc đó đang giữa tiến trình. Thì này cũng dùng để nói về việc chắc chắn sẽ xảy ra theo lệ thường, và để hỏi thăm kế hoạch một cách lịch sự mà không tạo cảm giác nhờ vả."},{"p":"Cấu trúc chính: will be + V-ing"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): At nine tomorrow I will be driving to work. (Hành động đang diễn ra tại mốc tương lai | Việc chắc chắn xảy ra theo lệ thường | Hỏi thăm kế hoạch một cách lịch sự)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Hành động đang diễn ra tại mốc tương lai: Mốc thời gian thường là giờ cụ thể hoặc một mệnh đề chỉ thời gian. (This time next week I will be sitting the exam.)"},{"p":"Việc chắc chắn xảy ra theo lệ thường: Diễn tả việc đã nằm trong lịch hoặc lệ thường. (I will be seeing her at the meeting anyway.)"},{"p":"Hỏi thăm kế hoạch một cách lịch sự: Will you be … tránh được sắc thái nhờ vả của Will you … (Will you be using the car tonight?)"},{"p":"Dự đoán việc đang diễn ra tại mốc đó: Dùng khi suy đoán về tình hình tại một mốc tương lai. (Don't call at eight — they will be having dinner.)"},{"p":"Ghi nhớ: Diễn tả hành động đang diễn ra tại một thời điểm trong tương lai."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: will be + V-ing"},{"table":[["Dạng thức","Công thức / Dấu hiệu","Ví dụ"],["Khẳng định","S + will be + V-ing","She will be working."],["Phủ định","won't be + V-ing","They won't be waiting."],["Nghi vấn","Will + S + be + V-ing?","Will you be joining us?"],["Mốc thời gian","at + giờ, this time tomorrow, when you arrive","At six I will be travelling."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Giữ nguyên thành phần be: Cấu trúc gồm ba phần: will, be và V-ing; thiếu be là lỗi phổ biến nhất. (will be driving)"},{"p":"02. Không chia will theo chủ ngữ: Will là động từ khuyết thiếu nên giữ nguyên với mọi chủ ngữ. (He will be… / They will be…)"},{"p":"03. Dùng hiện tại đơn ở mệnh đề thời gian: Sau when, by the time, as soon as thì không dùng will. (When you arrive, I will be waiting.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Mốc giờ cụ thể","At nine tomorrow I will be driving to work.\n(Chín giờ mai tôi đang trên đường đi làm.)","Tại mốc chín giờ, hành động đã bắt đầu và chưa kết thúc."],["This time next week","This time next week we will be sitting the final exam.\n(Giờ này tuần sau chúng tôi đang làm bài thi cuối kì.)","Cụm this time next week là mốc tương lai điển hình của thì này."],["Việc theo lệ thường","I will be seeing Mai at the meeting, so I can pass on the message.\n(Tôi sẽ gặp Mai ở cuộc họp nên có thể chuyển lời.)","Việc gặp là điều chắc chắn xảy ra theo lịch, không phải dự định mới nảy ra."],["Hỏi lịch sự","Will you be using the car tonight?\n(Tối nay bạn có dùng xe không?)","Cách hỏi này chỉ tìm hiểu kế hoạch, không mang sắc thái nhờ vả như Will you lend me the car?"],["Dự đoán tình hình","Don't call at eight — they will be having dinner.\n(Đừng gọi lúc tám giờ, lúc đó họ đang ăn cơm.)","Người nói suy đoán việc đang diễn ra tại mốc tám giờ."],["Với mệnh đề thời gian","When you arrive, I will be waiting at the gate.\n(Khi bạn đến, tôi đang đợi ở cổng.)","Mệnh đề sau when dùng hiện tại đơn, mệnh đề chính dùng tương lai tiếp diễn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cách nói về tương lai"},{"table":[["Cấu trúc","Cách nhìn","Ví dụ"],["will + V","sự việc sẽ xảy ra, nhìn như một điểm","I will arrive at six."],["will be + V-ing","sự việc đang diễn ra tại mốc đó","I will be travelling at six."],["will have + V3","sự việc sẽ hoàn tất trước mốc đó","I will have arrived by six."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: At nine tomorrow I will driving to work. → Đã sửa: At nine tomorrow I will be driving to work. — Thiếu be thì cấu trúc chưa hoàn chỉnh."},{"p":"Chưa đúng: When you will arrive, I will be waiting. → Đã sửa: When you arrive, I will be waiting. — Mệnh đề chỉ thời gian trong tương lai dùng hiện tại đơn, không dùng will."},{"p":"Chưa đúng: She will be knowing the answer tomorrow. → Đã sửa: She will know the answer tomorrow. — Know là động từ chỉ trạng thái nên không dùng dạng tiếp diễn."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cấu trúc có đủ will, be và V-ing."},{"p":"Mốc thời gian tương lai đã được nêu rõ."},{"p":"Mệnh đề chỉ thời gian dùng hiện tại đơn, không dùng will."},{"p":"Động từ không thuộc nhóm chỉ trạng thái."}]}],"id":"b1-07"},{"n":8,"title":"Future time clauses","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi nói về hai sự việc trong tương lai, tiếng Anh chỉ đặt dấu hiệu tương lai ở mệnh đề chính. Mệnh đề chỉ thời gian dùng hiện tại đơn hoặc hiện tại hoàn thành nếu muốn nhấn rằng việc đó phải hoàn tất trước. Nguyên tắc này giống với mệnh đề if trong câu điều kiện loại 1."},{"p":"Cấu trúc chính: when/as soon as/until + hiện tại đơn, will + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I will call you as soon as I arrive. (Nêu mốc thời gian cho một việc tương lai | Nhấn mạnh sự tức thì | Nêu giới hạn thời gian)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu mốc thời gian cho một việc tương lai: When và as soon as giới thiệu thời điểm việc chính sẽ xảy ra. (We will leave when the rain stops.)"},{"p":"Nhấn mạnh sự tức thì: As soon as nhấn rằng việc chính xảy ra ngay sau đó. (Call me as soon as you land.)"},{"p":"Nêu giới hạn thời gian: Until nêu mốc mà việc chính kéo dài đến; by the time nêu mốc mà việc đã xong trước đó. (Wait here until I come back.)"},{"p":"Nhấn việc phải hoàn tất trước: Dùng hiện tại hoàn thành trong mệnh đề thời gian khi thứ tự trước sau cần rõ. (I will go out after I have finished this.)"},{"p":"Ghi nhớ: Sau when, as soon as, until, before, after thì dùng hiện tại đơn dù câu nói về tương lai."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: when/as soon as/until + hiện tại đơn, will + V"},{"table":[["Thành phần","Công thức","Ví dụ"],["Mệnh đề thời gian","when, as soon as, until, before, after, by the time + hiện tại đơn","before you leave"],["Mệnh đề chính","will + V | be going to + V | mệnh lệnh","I will wait. / Call me."],["Nhấn hoàn tất trước","after/when + hiện tại hoàn thành","when I have read it"],["Trật tự đảo","Mệnh đề chính + mệnh đề thời gian (không dấu phẩy) | Mệnh đề thời gian + dấu phẩy + mệnh đề chính","I will call you when I arrive. / When I arrive, I will call you."],["Be trong mệnh đề thời gian","when/until + S + am/is/are (be cũng ở hiện tại đơn, không phải will be)","when I am free / until the paper is accepted"],["while","while + hành động đang diễn ra song song","Readings are logged while the drill is running."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mệnh đề nào nêu thời gian: Mệnh đề bắt đầu bằng when, as soon as, until, before, after là mệnh đề thời gian. (as soon as I arrive)"},{"p":"02. Dùng hiện tại đơn trong mệnh đề thời gian: Không dùng will dù nội dung thuộc tương lai. (when the rain stops)"},{"p":"03. Đặt dấu hiệu tương lai ở mệnh đề chính: Will, be going to hoặc dạng mệnh lệnh đều chỉ xuất hiện ở mệnh đề chính. (We will leave…)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["As soon as","I will call you as soon as I arrive at the hotel.\n(Tôi sẽ gọi cho bạn ngay khi đến khách sạn.)","Mệnh đề as soon as dùng hiện tại đơn arrive, còn will chỉ xuất hiện ở mệnh đề chính."],["When","We will leave when the rain stops.\n(Chúng ta sẽ đi khi nào trời tạnh.)","Stops ở hiện tại đơn dù việc trời tạnh thuộc tương lai."],["Until","Please wait here until I come back.\n(Bạn đợi ở đây đến khi tôi quay lại nhé.)","Mệnh đề chính ở dạng mệnh lệnh, mệnh đề until vẫn dùng hiện tại đơn."],["By the time","By the time you read this, I will have left.\n(Khi bạn đọc dòng này thì tôi đã đi rồi.)","By the time đi với hiện tại đơn, mệnh đề chính dùng tương lai hoàn thành."],["Hiện tại hoàn thành","I will go out after I have finished this report.\n(Tôi sẽ ra ngoài sau khi làm xong báo cáo này.)","Hiện tại hoàn thành nhấn rằng việc viết báo cáo phải xong trước khi đi."],["Trật tự đảo","When you get home, send me a message.\n(Khi về đến nhà thì nhắn cho tôi nhé.)","Mệnh đề thời gian đứng trước thì có dấu phẩy; đứng sau thì không cần."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba loại mệnh đề không dùng will"},{"table":[["Loại mệnh đề","Liên từ / Chức năng","Ví dụ"],["mệnh đề thời gian","when, as soon as, until, before, after","when he arrives"],["mệnh đề điều kiện","if, unless, as long as","if he arrives"],["mệnh đề chính","đây là nơi duy nhất có will","I will tell him."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I will call you as soon as I will arrive. → Đã sửa: I will call you as soon as I arrive. — Mệnh đề thời gian không dùng will."},{"p":"Chưa đúng: We will leave when the rain will stop. → Đã sửa: We will leave when the rain stops. — Dấu hiệu tương lai chỉ nằm ở mệnh đề chính."},{"p":"Chưa đúng: I will wait until he will not come. → Đã sửa: I will wait until he comes. — Until đã mang nghĩa đến khi nào, nên không dùng thêm phủ định."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mệnh đề thời gian dùng hiện tại đơn."},{"p":"Will chỉ xuất hiện ở mệnh đề chính."},{"p":"Hiện tại hoàn thành dùng khi cần nhấn việc hoàn tất trước."},{"p":"Dấu phẩy chỉ đặt khi mệnh đề thời gian đứng trước."},{"p":"Sau when hoặc after, hiện tại hoàn thành vẫn dùng has hoặc have, không dùng will."}]}],"id":"b1-08"},{"n":9,"title":"Used to, would & be used to","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ba cấu trúc này gần nhau về hình thức nhưng khác hẳn về nghĩa. Used to + động từ nguyên mẫu nói về thói quen hoặc trạng thái trong quá khứ nay không còn. Would + động từ nguyên mẫu cũng nói về thói quen quá khứ nhưng chỉ dùng cho hành động, không dùng cho trạng thái. Be used to + V-ing hoặc danh từ nói về việc đã quen với điều gì, và có thể ở bất kì thì nào."},{"p":"Cấu trúc chính: used to + V | be used to + V-ing/danh từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I used to walk to school, but now I am used to taking the bus. (Thói quen quá khứ nay không còn | Trạng thái quá khứ nay đã thay đổi | Kể lại hành động lặp lại trong hồi ức)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Thói quen quá khứ nay không còn: Used to nhấn mạnh sự tương phản giữa quá khứ và hiện tại. (I used to smoke, but I stopped.)"},{"p":"Trạng thái quá khứ nay đã thay đổi: Chỉ used to dùng được với động từ chỉ trạng thái, would thì không. (There used to be a cinema here.)"},{"p":"Kể lại hành động lặp lại trong hồi ức: Would thường dùng trong văn kể để nhắc lại những việc thường làm. (Every summer we would visit my grandparents.)"},{"p":"Đã quen với một việc: Be used to + V-ing diễn tả trạng thái không còn thấy lạ hay khó nữa. (She is used to working at night.)"},{"p":"Ghi nhớ: Used to + V nói về thói quen đã dứt; be used to + V-ing nói về trạng thái đã quen."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: used to + V | be used to + V-ing/danh từ"},{"table":[["Cấu trúc","Công thức","Ví dụ"],["used to","S + used to + V nguyên mẫu","He used to play football."],["Phủ định và nghi vấn","didn't use to + V | Did + S + use to + V?","I didn't use to like coffee."],["would","S + would + V nguyên mẫu (chỉ hành động)","We would go fishing every Sunday."],["be used to","S + am/is/are/was/were used to + V-ing hoặc danh từ","I am used to the noise."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt thói quen và sự đã quen: Thói quen đã dứt thì dùng used to; đã quen với điều gì thì dùng be used to. (I used to drive. ↔ I am used to driving.)"},{"p":"02. Chọn dạng động từ theo sau: Used to đi với động từ nguyên mẫu; be used to đi với V-ing hoặc danh từ. (used to walk / used to walking)"},{"p":"03. Kiểm tra would có dùng được hay không: Would chỉ thay thế used to khi nói về hành động lặp lại, không dùng cho trạng thái. (There used to be… không đổi thành There would be…)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Thói quen đã dứt","I used to walk to school when I was a child.\n(Hồi nhỏ tôi hay đi bộ đến trường.)","Used to đi với động từ nguyên mẫu walk và hàm ý nay không còn như vậy."],["Đã quen","Now I am used to taking the bus every day.\n(Giờ tôi đã quen với việc đi xe buýt hằng ngày.)","Be used to đi với V-ing; cấu trúc nói về trạng thái hiện tại, không phải quá khứ."],["Trạng thái quá khứ","There used to be a cinema on this street.\n(Trước đây, phố này có một rạp chiếu phim.)","Would không dùng được ở đây vì be là động từ chỉ trạng thái."],["Hồi ức với would","Every summer my grandmother would make plum jam.\n(Mỗi mùa hè, bà tôi thường làm mứt mận.)","Would nhắc lại hành động lặp lại trong hồi ức, giọng kể hơn used to."],["Phủ định","I didn't use to like coffee, but now I drink it every morning.\n(Trước tôi không thích cà phê, giờ thì sáng nào cũng uống.)","Dạng phủ định là didn't use to, bỏ chữ d ở use."],["Be used to ở quá khứ","After a month she was used to the noise of the city.\n(Sau một tháng, cô ấy đã quen với tiếng ồn của thành phố.)","Be used to chia được ở mọi thì vì phần biến đổi là động từ be."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cấu trúc, ba nghĩa"},{"table":[["Cấu trúc","Nghĩa","Ví dụ"],["used to + V","thói quen hoặc trạng thái quá khứ, nay không còn","I used to live in Hue."],["would + V","hành động lặp lại trong quá khứ, giọng hồi ức","We would play outside all day."],["be used to + V-ing","đã quen, dùng được ở mọi thì","I am used to living alone."],["get used to + V-ing","đang dần quen","He is getting used to the new job."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I am used to walk to school when I was young. → Đã sửa: I used to walk to school when I was young. — Thói quen quá khứ dùng used to + động từ nguyên mẫu, không dùng be used to."},{"p":"Chưa đúng: She is used to work at night. → Đã sửa: She is used to working at night. — Sau be used to là V-ing hoặc danh từ."},{"p":"Chưa đúng: There would be a cinema here. → Đã sửa: There used to be a cinema here. — Would không dùng cho trạng thái, chỉ dùng cho hành động lặp lại."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Nội dung là thói quen đã dứt hay trạng thái đã quen."},{"p":"Dạng động từ theo sau đúng với từng cấu trúc."},{"p":"Would chỉ dùng cho hành động lặp lại."},{"p":"Dạng phủ định viết là didn't use to."}]}],"id":"b1-09"},{"n":10,"title":"Gerunds & infinitives","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi hai động từ đứng cạnh nhau, động từ thứ hai phải đổi dạng và dạng đó do động từ thứ nhất quyết định. Không có quy tắc nghĩa nào đoán được, nên cách học hiệu quả là nhớ theo nhóm. Có nhóm đi với V- ing, nhóm đi với to-V, nhóm đi với động từ nguyên mẫu không to và nhóm dùng được cả hai dạng mà nghĩa không đổi."},{"p":"Cấu trúc chính: enjoy + V-ing | decide + to-V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She enjoys reading and has decided to join a book club. (Sau động từ chỉ sự ưa thích | Sau động từ chỉ ý định và quyết định | Sau giới từ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Sau động từ chỉ sự ưa thích: Enjoy, like, love, hate, mind, avoid, finish, keep đi với V-ing. (I avoid eating late.)"},{"p":"Sau động từ chỉ ý định và quyết định: Decide, want, hope, plan, promise, agree, offer đi với to-V. (They agreed to help.)"},{"p":"Sau giới từ: Khi bổ ngữ của giới từ là động từ, thường dùng dạng V-ing, kể cả khi to là giới từ (phân biệt với to trong to-V như I want to meet you). Giới từ cũng có thể đi với danh từ hoặc đại từ (after class, with her). (I look forward to meeting you. / after studying)"},{"p":"Làm chủ ngữ của câu: V-ing dùng làm chủ ngữ tự nhiên hơn to-V trong tiếng Anh hằng ngày. (Swimming is good exercise.)"},{"p":"Ghi nhớ: Mỗi động từ chi phối một dạng riêng ở phía sau: enjoy đi với V-ing, decide đi với to-V."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: enjoy + V-ing | decide + to-V"},{"table":[["Nhóm cấu trúc","Động từ đi kèm","Ví dụ"],["+ V-ing","enjoy, avoid, mind, finish, keep, suggest, practise, give up","She finished writing the report."],["+ to-V","decide, want, hope, plan, promise, agree, offer, manage, refuse","He refused to answer."],["+ tân ngữ + to-V","ask, tell, advise, want, expect, allow + O + to-V","She asked me to wait."],["+ V nguyên mẫu không to","make, let, help, các động từ khuyết thiếu","Let me explain. / She made him apologise."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Tìm động từ chi phối: Động từ đứng trước quyết định dạng của động từ theo sau, không phải nghĩa của câu. (enjoy → V-ing)"},{"p":"02. Kiểm tra có giới từ hay không: Nếu vị trí cần điền là động từ đứng ngay sau giới từ thì dùng dạng V-ing (giới từ cũng có thể đi với danh từ hoặc đại từ). (interested in learning)"},{"p":"03. Nhớ nhóm động từ cần tân ngữ ở giữa: Ask, tell, advise, allow, expect cần một tân ngữ trước to-V. (She asked me to wait.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Sau enjoy","She enjoys reading before bed.\n(Cô ấy thích đọc sách trước khi ngủ.)","Enjoy luôn đi với V-ing; enjoy to read là sai."],["Sau decide","They decided to move to Da Nang.\n(Họ quyết định chuyển ra Đà Nẵng.)","Decide thuộc nhóm đi với động từ nguyên mẫu có to."],["Sau giới từ","I am looking forward to meeting your family.\n(Tôi rất mong được gặp gia đình bạn.)","Trong cụm look forward to, chữ to là giới từ nên theo sau là V-ing."],["Tân ngữ ở giữa","The teacher asked us to hand in our essays.\n(Thầy yêu cầu chúng tôi nộp bài luận.)","Ask cần một tân ngữ trước to-V."],["Nguyên mẫu không to","My parents let me choose my own subjects.\n(Bố mẹ để tôi tự chọn môn học.)","Let, make và help đi với động từ nguyên mẫu không to."],["Làm chủ ngữ","Learning a language takes time and patience.\n(Học một ngôn ngữ cần thời gian và sự kiên nhẫn.)","V-ing làm chủ ngữ và kéo theo động từ số ít."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn mẫu kết hợp cần nhớ"},{"table":[["Mẫu cấu trúc","Nhóm động từ","Ví dụ"],["V + V-ing","enjoy, avoid, finish, mind","I don't mind waiting."],["V + to-V","decide, hope, promise, manage","She managed to finish."],["V + O + to-V","ask, tell, advise, allow","They allowed us to stay."],["V + O + V nguyên mẫu","make, let, help","She made us laugh."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She enjoys to read. → Đã sửa: She enjoys reading. — Enjoy thuộc nhóm đi với V-ing."},{"p":"Chưa đúng: I look forward to meet you. → Đã sửa: I look forward to meeting you. — Trong cụm này, to là giới từ nên theo sau là V-ing."},{"p":"Chưa đúng: He suggested me to call the office. → Đã sửa: He suggested calling the office. — Suggest không đi với tân ngữ và to-V; nó đi với V-ing hoặc một mệnh đề that."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ chi phối thuộc nhóm nào."},{"p":"Trước vị trí cần điền có giới từ hay không."},{"p":"Động từ có cần tân ngữ trước to-V hay không."},{"p":"Dạng V-ing hoặc to-V đã viết đúng chính tả."}]}],"id":"b1-10"},{"n":11,"title":"Be able to & be allowed to","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Can và may là động từ khuyết thiếu nên chỉ có hai dạng và không đi được sau một động từ khuyết thiếu khác. Khi cần nói về khả năng hoặc sự cho phép ở tương lai, ở dạng hoàn thành, hay sau một động từ khuyết thiếu, tiếng Anh dùng be able to và be allowed to. Ngoài ra manage to nhấn rằng việc đó khó nhưng đã làm được."},{"p":"Cấu trúc chính: be able to + V | be allowed to + V | manage to + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I will be able to join you, but we won't be allowed to park there. (Khả năng ở tương lai và dạng hoàn thành | Sự cho phép theo quy định | Nhấn rằng việc khó nhưng đã làm được)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Khả năng ở tương lai và dạng hoàn thành: Can không có dạng tương lai hay hoàn thành nên dùng be able to. (I will be able to drive next year.)"},{"p":"Sự cho phép theo quy định: Be allowed to nêu điều được phép theo nội quy, dùng được ở mọi thì. (We aren't allowed to eat in the library.)"},{"p":"Nhấn rằng việc khó nhưng đã làm được: Manage to dùng cho một lần cụ thể, không dùng cho khả năng chung. (She managed to fix it herself.)"},{"p":"Khả năng chung và một lần cụ thể: Could nói về khả năng chung trong quá khứ; was able to hoặc managed to nói về một lần thành công cụ thể. (He could swim at five. / He was able to swim to the boat.)"},{"p":"Ghi nhớ: Be able to thay can ở những thì mà can không có dạng; be allowed to thay may để nói về sự cho phép."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: be able to + V | be allowed to + V | manage to + V"},{"table":[["Chức năng","Công thức","Ví dụ"],["Khả năng","am/is/are/was/were/will be/have been able to + V","She has been able to work from home."],["Sự cho phép","am/is/are/was/were/will be allowed to + V","Students are allowed to use dictionaries."],["Thành công một lần","managed to + V | succeeded in + V-ing","They managed to reach the summit."],["Sau động từ khuyết thiếu khác","must/might/should + be able to + V","You might be able to catch him."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Kiểm tra thì cần dùng: Hiện tại và quá khứ đơn thì can và could là đủ; các thì khác cần be able to. (can swim ↔ will be able to swim)"},{"p":"02. Chia động từ be theo thì và chủ ngữ: Phần able to và allowed to giữ nguyên, chỉ be biến đổi. (She was able to… / They will be allowed to…)"},{"p":"03. Chọn giữa khả năng chung và một lần: Khả năng chung trong quá khứ dùng could; một lần thành công cụ thể dùng was able to hoặc managed to. (I could read ↔ I was able to find it)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Tương lai","I will be able to join you next week.\n(Tuần sau tôi sẽ tham gia cùng các bạn được.)","Can không có dạng tương lai nên phải dùng will be able to."],["Sự cho phép phủ định","We aren't allowed to park in front of the gate.\n(Chúng ta không được đỗ xe trước cổng.)","Be allowed to nêu điều bị quy định không cho phép."],["Dạng hoàn thành","She has been able to work from home since March.\n(Từ tháng Ba cô ấy làm việc ở nhà được.)","Dạng hoàn thành của can là have been able to."],["Sau động từ khuyết thiếu khác","If you hurry, you might be able to catch him.\n(Nếu bạn nhanh thì có thể bắt kịp anh ấy.)","Không thể viết might can, nên phải dùng might be able to."],["Thành công một lần","The door was stuck, but she managed to open it.\n(Cửa bị kẹt nhưng cô ấy mở được.)","Managed to nhấn rằng việc khó nhưng đã thành công ở lần cụ thể đó."],["Khả năng chung và một lần","He could swim at the age of five, and last summer he was able to swim across the lake.\n(Cậu ấy biết bơi từ năm tuổi và hè năm ngoái bơi được qua hồ.)","Could cho khả năng chung, was able to cho một lần thành công cụ thể."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chọn cấu trúc theo thì và sắc thái"},{"table":[["Cấu trúc","Sắc thái / Phạm vi","Ví dụ"],["can / could","khả năng ở hiện tại và khả năng chung trong quá khứ","I can drive. / I could swim as a child."],["be able to","dùng được ở mọi thì và sau động từ khuyết thiếu khác","I will be able to drive."],["managed to","một lần thành công dù khó","I managed to pass."],["be allowed to","sự cho phép theo quy định","We are allowed to leave early."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I will can join you next week. → Đã sửa: I will be able to join you next week. — Hai động từ khuyết thiếu không đứng liền nhau."},{"p":"Chưa đúng: We aren't allowed park here. → Đã sửa: We aren't allowed to park here. — Cấu trúc là be allowed to cộng động từ nguyên mẫu."},{"p":"Chưa đúng: The door was stuck, but she could open it. → Đã sửa: The door was stuck, but she managed to open it. — Một lần thành công cụ thể trong quá khứ dùng managed to hoặc was able to, không dùng could."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Thì của câu có cho phép dùng can hay không."},{"p":"Động từ be đã chia đúng theo thì và chủ ngữ."},{"p":"Hai động từ khuyết thiếu không đứng liền nhau."},{"p":"Could và managed to dùng đúng sắc thái khả năng chung hoặc một lần cụ thể."}]}],"id":"b1-11"},{"n":12,"title":"Modals of deduction","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi không biết chắc một điều, người nói dùng động từ khuyết thiếu để thể hiện mức độ tin tưởng của mình. Must là suy đoán ở mức cao nhất, dựa trên bằng chứng. May và might ở mức trung bình. Can't là kết luận phủ định ở mức cao nhất, nghĩa là không thể nào. Lưu ý mustn't không phải dạng phủ định của must trong nghĩa suy đoán."},{"p":"Cấu trúc chính: must/may/might/can't + V nguyên mẫu"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The lights are off, so they must be out. (Kết luận gần như chắc chắn | Nêu khả năng | Loại trừ một khả năng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Kết luận gần như chắc chắn: Must dùng khi có bằng chứng dẫn đến một kết luận duy nhất hợp lí. (She knows everyone here — she must work here.)"},{"p":"Nêu khả năng: May và might đều chỉ khả năng; might nghe dè dặt hơn một chút. (He may be in a meeting. / It might rain later.)"},{"p":"Loại trừ một khả năng: Can't dùng khi bằng chứng cho thấy điều đó không thể xảy ra. (That can't be Nam — he is in Hue.)"},{"p":"Suy đoán về việc đang diễn ra: Thêm be + V-ing sau động từ khuyết thiếu. (They must be having lunch.)"},{"p":"Ghi nhớ: Must chỉ suy đoán gần như chắc chắn, may và might chỉ khả năng, can't chỉ điều không thể."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: must/may/might/can't + V nguyên mẫu"},{"table":[["Mức độ","Công thức","Ví dụ"],["Mức cao","must + V nguyên mẫu","He must be tired."],["Mức trung bình","may / might / could + V nguyên mẫu","She might know the answer."],["Phủ định mức cao","can't / couldn't + V nguyên mẫu","It can't be true."],["Suy đoán về việc đang diễn ra","động từ khuyết thiếu + be + V-ing","They may be waiting outside."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mức độ tin tưởng: Có bằng chứng rõ thì dùng must hoặc can't; chỉ phỏng đoán thì dùng may, might, could. (must be ↔ might be)"},{"p":"02. Dùng động từ nguyên mẫu không to: Mọi động từ khuyết thiếu đều giữ nguyên dạng và không chia theo chủ ngữ. (She must know, không phải She musts know)"},{"p":"03. Chọn đúng dạng phủ định theo nghĩa: Phủ định của suy đoán must là can't, còn mustn't mang nghĩa cấm. (He can't be at home. ↔ You mustn't smoke.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Suy đoán mức cao","The lights are off, so they must be out.\n(Đèn tắt hết rồi, chắc họ đi ra ngoài.)","Must dựa trên bằng chứng là đèn tắt để đi tới kết luận hợp lí nhất."],["Loại trừ","That can't be Nam — he is in Hue this week.\n(Không thể là Nam được, tuần này cậu ấy ở Huế.)","Can't là kết luận phủ định mức cao, không phải mustn't."],["Nêu khả năng","She isn't answering. She may be in a meeting.\n(Cô ấy không trả lời. Có thể cô ấy đang họp.)","May chỉ một khả năng, không khẳng định chắc chắn."],["Dè dặt hơn","It might rain this afternoon, so take an umbrella.\n(Chiều nay có thể mưa, bạn mang theo dù nhé.)","Might nghe dè dặt hơn may, nhưng trong thực tế hai từ gần như thay thế nhau được."],["Suy đoán về việc đang diễn ra","It's noon — they must be having lunch now.\n(Trưa rồi, chắc họ đang ăn cơm.)","Thêm be + V-ing để suy đoán về việc đang diễn ra ngay lúc nói."],["Chuỗi suy luận","He can't be at work, and he isn't at home, so he might be at the gym.\n(Anh ấy không thể đang ở cơ quan, cũng không ở nhà, nên có lẽ đang ở phòng tập.)","Ba mức độ suy đoán xuất hiện trong một mạch lập luận."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Thang mức độ suy đoán"},{"table":[["Động từ","Sắc thái","Ví dụ"],["must","gần như chắc chắn là có","She must be the new teacher."],["may / might / could","có thể","She might be the new teacher."],["may not / might not","có thể không","She might not be here yet."],["can't","gần như chắc chắn là không","She can't be the new teacher."],["should","suy đoán điều hợp lẽ sẽ xảy ra (ắt sẽ, theo lý mà nói), nhẹ hơn must","If the method is sound, the two runs should agree."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The lights are off, so they mustn't be at home. → Đã sửa: The lights are off, so they can't be at home. — Phủ định của suy đoán must là can't; mustn't mang nghĩa cấm."},{"p":"Chưa đúng: She must to be tired. → Đã sửa: She must be tired. — Sau động từ khuyết thiếu là động từ nguyên mẫu không to."},{"p":"Chưa đúng: He may is at the office. → Đã sửa: He may be at the office. — Sau may là dạng nguyên mẫu be, không phải dạng đã chia is."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mức độ tin tưởng của người nói đã được thể hiện đúng."},{"p":"Động từ sau động từ khuyết thiếu ở dạng nguyên mẫu không to."},{"p":"Phủ định của suy đoán dùng can't, không dùng mustn't."},{"p":"Suy đoán về việc đang diễn ra có thêm be + V-ing."},{"p":"Văn nói cũng dùng have to be cho suy luận chắc chắn: the sensors have to be linked."}]}],"id":"b1-12"},{"n":13,"title":"Ought to, had better & need","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhóm cấu trúc này bổ sung sắc thái cho should. Ought to gần như đồng nghĩa với should nhưng nghe trang trọng hơn và thường gắn với bổn phận. Had better mạnh hơn, hàm ý nếu không làm thì sẽ có hậu quả xấu, nên thường đi kèm mệnh đề cảnh báo. Need to nêu sự cần thiết khách quan, và dạng phủ định needn't nghĩa là không cần."},{"p":"Cấu trúc chính: ought to + V | had better + V | need to + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): You had better leave now or you will miss the train. (Lời khuyên mang tính bổn phận | Cảnh báo kèm hậu quả | Nêu sự cần thiết)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Lời khuyên mang tính bổn phận: Ought to dùng khi điều đó là đúng đắn hoặc hợp lẽ. (You ought to apologise.)"},{"p":"Cảnh báo kèm hậu quả: Had better thường đi với or hoặc otherwise để nêu hậu quả. (You had better hurry or you'll be late.)"},{"p":"Nêu sự cần thiết: Need to chia theo chủ ngữ và có mọi thì như một động từ thường. (She needs to renew her passport.)"},{"p":"Nói điều không cần thiết: Needn't và don't need to đều nghĩa là không cần. (You needn't bring anything.)"},{"p":"Ghi nhớ: Ought to tương đương should, had better cảnh báo hậu quả, need to nêu sự cần thiết."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: ought to + V | had better + V | need to + V"},{"table":[["Cấu trúc","Công thức","Ví dụ"],["ought to","S + ought (not) to + V nguyên mẫu","We ought to tell her."],["had better","S + had better ('d better) (not) + V nguyên mẫu","You'd better not be late."],["need to","S + need(s) to + V | don't/doesn't need to + V","He needs to rest."],["needn't","S + needn't + V nguyên mẫu","You needn't wait for me."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn mức độ phù hợp: Ought to là lời khuyên, had better là cảnh báo, need to là sự cần thiết. (ought to rest ↔ had better rest or you'll get worse)"},{"p":"02. Nhớ dạng động từ theo sau từng cấu trúc: Ought to và need to có chữ to; had better thì không. (had better leave, không phải had better to leave)"},{"p":"03. Đặt not vào vị trí đúng: Dạng phủ định là ought not to, had better not, needn't. (You'd better not tell him.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Cảnh báo","You had better leave now or you will miss the train.\n(Bạn nên đi ngay không thì trễ tàu.)","Had better đi với động từ nguyên mẫu không to và mệnh đề sau or nêu hậu quả."],["Lời khuyên trang trọng","You ought to apologise to her.\n(Bạn nên xin lỗi cô ấy.)","Ought to có chữ to, khác với had better; sắc thái gắn với lẽ phải."],["Sự cần thiết","She needs to renew her passport before the trip.\n(Cô ấy cần làm lại hộ chiếu trước chuyến đi.)","Need to chia theo chủ ngữ nên she kéo theo needs to."],["Không cần thiết","You needn't bring anything — we have enough food.\n(Bạn không cần mang gì cả, thức ăn đã đủ.)","Needn't là động từ khuyết thiếu nên theo sau là động từ nguyên mẫu không to."],["Phủ định của had better","You'd better not say anything about the surprise.\n(Bạn đừng nói gì về món quà bất ngờ đó.)","Not đặt sau better, trước động từ nguyên mẫu."],["Phủ định của ought to","He ought not to drive after such a long day.\n(Anh ấy không nên lái xe sau một ngày dài như vậy.)","Not chen vào giữa ought và to."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn mức độ khuyên bảo"},{"table":[["Cấu trúc","Sắc thái","Ví dụ"],["should / ought to","lời khuyên","You should rest."],["had better","cảnh báo có hậu quả","You'd better rest or you'll get ill."],["need to","sự cần thiết khách quan","You need to rest for a week."],["must / have to","bắt buộc","You must rest — doctor's orders."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: You had better to leave now. → Đã sửa: You had better leave now. — Had better đi với động từ nguyên mẫu không to."},{"p":"Chưa đúng: You ought apologise to her. → Đã sửa: You ought to apologise to her. — Ought luôn đi kèm to."},{"p":"Chưa đúng: She need to renews her passport. → Đã sửa: She needs to renew her passport. — Need to chia theo chủ ngữ, còn động từ sau to giữ dạng nguyên mẫu."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Sắc thái là khuyên, cảnh báo hay nêu sự cần thiết."},{"p":"Cấu trúc có chữ to hay không."},{"p":"Need to đã chia đúng theo chủ ngữ."},{"p":"Vị trí của not đúng với từng cấu trúc."}]}],"id":"b1-13"},{"n":14,"title":"Clauses of purpose","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mục đích trả lời câu hỏi làm việc đó để làm gì. Tiếng Anh có ba cách diễn đạt và chúng khác nhau về thành phần đi sau: to-V và in order to đi với một động từ nguyên mẫu; so that đi với một mệnh đề có chủ ngữ riêng; còn for đi với một danh từ chứ không đi với động từ. Lỗi phổ biến nhất là dùng for cộng động từ."},{"p":"Cấu trúc chính: to-V | in order to + V | so that + mệnh đề | for + danh từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She left early so that she could catch the last train. (Mục đích có cùng chủ ngữ | Mục đích có chủ ngữ khác | Văn phong trang trọng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Mục đích có cùng chủ ngữ: Dùng to-V khi người thực hiện hai việc là cùng một người. (I came here to study.)"},{"p":"Mục đích có chủ ngữ khác: Dùng so that khi người hưởng mục đích khác người thực hiện. (I spoke slowly so that everyone could understand.)"},{"p":"Văn phong trang trọng: In order to và in order that trang trọng hơn to-V và so that. (The rule was introduced in order to reduce accidents.)"},{"p":"Nêu mục đích bằng danh từ: For đi với danh từ; muốn dùng động từ thì phải đổi sang to-V hoặc for + V- ing khi nói về công dụng. (I went out for a walk. / This knife is for cutting bread.)"},{"p":"Ghi nhớ: To-V và in order to đi với động từ; so that đi với một mệnh đề; for đi với danh từ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: to-V | in order to + V | so that + mệnh đề | for + danh từ"},{"table":[["Cấu trúc","Công thức","Ví dụ"],["to-V","mệnh đề chính + to + V nguyên mẫu","She called to apologise."],["in order to / so as to","trang trọng hơn, phủ định là in order not to","in order not to disturb anyone"],["so that","so that + S + can/could/will/would + V","so that we could see better"],["for","for + danh từ | for + V-ing khi nói về công dụng","for the exam, for storing data"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xem hai việc có cùng chủ ngữ hay không: Cùng chủ ngữ thì dùng to-V; khác chủ ngữ thì dùng so that. (I left early to catch the train. ↔ I left early so that my brother could use the car.)"},{"p":"02. Chọn động từ khuyết thiếu sau so that: Mệnh đề chính ở hiện tại hoặc tương lai thì dùng can hoặc will; ở quá khứ thì dùng could hoặc would. (so that she can see ↔ so that she could see)"},{"p":"03. Không dùng for trước động từ nguyên mẫu: For chỉ đi với danh từ; nếu cần động từ thì dùng to-V. (for the train, không phải for catch the train)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Khác chủ ngữ","She left early so that she could catch the last train.\n(Cô ấy về sớm để kịp chuyến tàu cuối.)","Mệnh đề chính ở quá khứ nên so that đi với could."],["Cùng chủ ngữ","She left early to catch the last train.\n(Cô ấy về sớm để kịp chuyến tàu cuối.)","Cùng một người thực hiện hai việc nên to-V là cách gọn nhất."],["Chủ ngữ khác nhau","I spoke slowly so that everyone could understand me.\n(Tôi nói chậm để mọi người hiểu được.)","Người nói và người hiểu là hai bên khác nhau nên bắt buộc dùng so that."],["Văn phong trang trọng","The rule was introduced in order to reduce accidents.\n(Quy định này được đưa ra nhằm giảm tai nạn.)","In order to trang trọng hơn to-V và thường gặp trong văn bản."],["Phủ định","He closed the door quietly in order not to wake the baby.\n(Anh ấy đóng cửa nhẹ để không làm em bé thức giấc.)","Dạng phủ định là in order not to hoặc so as not to, không nói to not."],["For với danh từ và công dụng","I went out for a walk, and this bag is for carrying books.\n(Tôi ra ngoài đi bộ một chút và cái túi này dùng để đựng sách.)","For đi với danh từ a walk hoặc với V-ing khi nói về công dụng của vật."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cách nêu mục đích"},{"table":[["Cấu trúc","Cách dùng","Ví dụ"],["to-V","cùng chủ ngữ, gọn và thông dụng","I stayed up to finish it."],["so that + mệnh đề","khác chủ ngữ hoặc cần nêu rõ ai hưởng mục đích","I stayed up so that you could sleep."],["for + danh từ","mục đích nêu bằng danh từ","I stayed up for the match."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She left early for catch the last train. → Đã sửa: She left early to catch the last train. — For không đi với động từ nguyên mẫu; mục đích dùng to-V."},{"p":"Chưa đúng: I spoke slowly so that everyone understand. → Đã sửa: I spoke slowly so that everyone could understand. — Mệnh đề so that cần một động từ khuyết thiếu như can, could, will hoặc would."},{"p":"Chưa đúng: He closed the door quietly to not wake the baby. → Đã sửa: He closed the door quietly in order not to wake the baby. — Dạng phủ định chuẩn mực là in order not to hoặc so as not to."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Hai việc có cùng chủ ngữ hay không."},{"p":"Mệnh đề so that có động từ khuyết thiếu phù hợp với thì."},{"p":"For không đứng trước động từ nguyên mẫu."},{"p":"Dạng phủ định dùng in order not to hoặc so as not to."}]}],"id":"b1-14"},{"n":15,"title":"Zero & first conditionals","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Câu điều kiện gồm hai mệnh đề: mệnh đề if nêu điều kiện, mệnh đề chính nêu kết quả. Loại 0 dùng khi điều kiện và kết quả luôn đi cùng nhau như một quy luật. Loại 1 dùng khi điều kiện có thật khả năng xảy ra trong tương lai. Nguyên tắc chi phối cả hai loại là mệnh đề if không bao giờ dùng will."},{"p":"Cấu trúc chính: If + hiện tại đơn, hiện tại đơn | If + hiện tại đơn, will + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): If it rains tomorrow, we will stay at home. (Quy luật và sự thật hiển nhiên | Hướng dẫn và quy định | Dự đoán kết quả trong tương lai)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Quy luật và sự thật hiển nhiên: Loại 0 dùng hiện tại đơn ở cả hai mệnh đề; if ở đây gần nghĩa với when. (If you heat ice, it melts.)"},{"p":"Hướng dẫn và quy định: Loại 0 với mệnh đề chính ở dạng mệnh lệnh. (If the light turns red, stop.)"},{"p":"Dự đoán kết quả trong tương lai: Loại 1 dùng will hoặc may, might, can khi muốn giảm mức chắc chắn. (If you study hard, you will pass.)"},{"p":"Lời cảnh báo, lời hứa, lời đề nghị: Loại 1 rất hay dùng cho những phát ngôn này. (If you touch that, you'll burn yourself.)"},{"p":"Ghi nhớ: Loại 0 nói về điều luôn đúng, loại 1 nói về điều có thật khả năng xảy ra trong tương lai."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: If + hiện tại đơn, hiện tại đơn | If + hiện tại đơn, will + V"},{"table":[["Loại câu","Công thức","Ví dụ"],["Loại 0","If + hiện tại đơn, hiện tại đơn","If water reaches 100°C, it boils."],["Loại 1","If + hiện tại đơn, will + V nguyên mẫu","If I see her, I will tell her."],["Biến thể của loại 1","may/might/can/should + V trong mệnh đề chính","If you hurry, you might catch the bus."],["Trật tự đảo","mệnh đề chính + if + điều kiện (không có dấu phẩy)","We will stay at home if it rains."],["Be trong mệnh đề if","If + S + is/are (be của hiện tại đơn), mệnh đề chính vẫn will + V","If the result is confirmed, the policy will change."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt quy luật và khả năng tương lai: Quy luật thì dùng loại 0; khả năng tương lai thì dùng loại 1. (If you heat ice, it melts. ↔ If it rains, we will stay in.)"},{"p":"02. Không dùng will trong mệnh đề if: Dấu hiệu tương lai chỉ xuất hiện ở mệnh đề chính. (If it rains tomorrow, …)"},{"p":"03. Đặt dấu phẩy theo trật tự câu: Mệnh đề if đứng trước thì có dấu phẩy; đứng sau thì không cần. (If you call, I'll answer. ↔ I'll answer if you call.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Loại 1","If it rains tomorrow, we will stay at home.\n(Nếu mai mưa thì chúng ta sẽ ở nhà.)","Mệnh đề if dùng hiện tại đơn dù nói về tương lai; will chỉ xuất hiện ở mệnh đề chính."],["Loại 0","If you heat ice, it melts.\n(Nếu đun nóng đá thì đá tan.)","Cả hai mệnh đề đều ở hiện tại đơn vì đây là một quy luật luôn đúng."],["Hướng dẫn","If the light turns red, stop immediately.\n(Nếu đèn chuyển đỏ thì dừng lại ngay.)","Mệnh đề chính ở dạng mệnh lệnh, thường thấy trong hướng dẫn và quy định."],["Giảm mức chắc chắn","If you hurry, you might catch the last bus.\n(Nếu bạn nhanh lên thì có thể kịp chuyến xe cuối.)","Might thay cho will khi người nói không chắc về kết quả."],["Cảnh báo","If you touch that pan, you'll burn yourself.\n(Nếu bạn chạm vào cái chảo đó thì sẽ bị bỏng.)","Loại 1 rất hay dùng cho lời cảnh báo về hậu quả trước mắt."],["Trật tự đảo","We will stay at home if it rains tomorrow.\n(Chúng ta sẽ ở nhà nếu mai mưa.)","Mệnh đề if đứng sau thì không cần dấu phẩy."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Phân biệt hai loại điều kiện đầu"},{"table":[["Loại / Từ","Đặc điểm","Ví dụ"],["Loại 0","luôn đúng, không phụ thuộc thời điểm","If I drink coffee at night, I can't sleep."],["Loại 1","có thật khả năng xảy ra trong tương lai","If I drink coffee tonight, I won't sleep."],["unless","nếu không, thay cho if … not","Unless you hurry, you'll be late."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: If it will rain tomorrow, we will stay at home. → Đã sửa: If it rains tomorrow, we will stay at home. — Mệnh đề if không dùng will, dù nội dung thuộc tương lai."},{"p":"Chưa đúng: If you will study hard, you pass. → Đã sửa: If you study hard, you will pass. — Dấu hiệu tương lai thuộc mệnh đề chính, không thuộc mệnh đề if."},{"p":"Chưa đúng: If you heat ice, it will melt always. → Đã sửa: If you heat ice, it melts. — Quy luật luôn đúng thì dùng loại 0 với hiện tại đơn ở cả hai mệnh đề."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Điều kiện là quy luật hay khả năng trong tương lai."},{"p":"Mệnh đề if không có will."},{"p":"Mệnh đề chính dùng đúng will hoặc dạng hiện tại đơn theo loại câu."},{"p":"Dấu phẩy đặt đúng theo trật tự hai mệnh đề."}]}],"id":"b1-15"},{"n":16,"title":"Second conditional","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Điều kiện loại 2 diễn tả một giả định ở hiện tại hoặc tương lai: điều kiện trái với thực tế hoặc rất khó xảy ra. Quá khứ đơn trong mệnh đề if đánh dấu tính giả định. Với động từ be, văn viết chuẩn dùng were cho mọi chủ ngữ."},{"p":"Cấu trúc chính: If + quá khứ đơn, would + V nguyên mẫu"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): If I had more time, I would learn the piano. (Tình huống trái với hiện tại | Điều rất khó xảy ra | Đưa ra lời khuyên một cách nhẹ nhàng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Tình huống trái với hiện tại: Người nói biết điều kiện không đúng với thực tế. (If I were rich, I would travel the world.)"},{"p":"Điều rất khó xảy ra: Dùng khi khả năng xảy ra là rất nhỏ. (If I won the lottery, I would buy a house.)"},{"p":"Đưa ra lời khuyên một cách nhẹ nhàng: Cấu trúc If I were you là mẫu khuyên bảo thông dụng. (If I were you, I would apologise.)"},{"p":"Nói về mong muốn và dự định giả định: Thường kết hợp với các động từ chỉ mong muốn. (If I had more time, I would take up a sport.)"},{"p":"Ghi nhớ: Nói về tình huống giả định trái với hiện tại hoặc khó xảy ra, dùng quá khứ đơn và would."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: If + quá khứ đơn, would + V nguyên mẫu"},{"table":[["Thành phần","Công thức","Ví dụ"],["Mệnh đề if","If + S + quá khứ đơn","If she studied harder, …"],["Mệnh đề chính","would / could / might + V nguyên mẫu","… she would get better marks."],["Với động từ be","If I/he/she/it were … (dạng chuẩn mực)","If he were here, he would help."],["Lời khuyên","If I were you, I would + V","If I were you, I'd take the job."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đặt mệnh đề if ở quá khứ đơn: Quá khứ đơn ở đây đánh dấu tính giả định, không chỉ thời gian quá khứ. (If I had more time…)"},{"p":"02. Dùng would trong mệnh đề chính: Could diễn tả khả năng, might diễn tả sự không chắc chắn. (I would learn / I could learn / I might learn)"},{"p":"03. Không dùng would trong mệnh đề if: Lỗi này phổ biến nhất ở điều kiện loại 2. (If I would have time → sai)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Trái với hiện tại","If I had more time, I would learn the piano.\n(Nếu tôi có nhiều thời gian hơn thì tôi sẽ học piano.)","Người nói hiện không có thời gian, nên điều kiện là giả định."],["Dùng were","If he were here, he would know what to do.\n(Nếu anh ấy ở đây thì anh ấy sẽ biết phải làm gì.)","Với điều kiện giả định, were dùng cho mọi chủ ngữ trong văn viết chuẩn mực."],["Lời khuyên","If I were you, I would apologise to her.\n(Nếu là bạn thì tôi sẽ xin lỗi cô ấy.)","If I were you là mẫu đưa ra lời khuyên rất thông dụng."],["Điều khó xảy ra","If I won the lottery, I would buy a house for my parents.\n(Nếu tôi trúng số thì tôi sẽ mua nhà cho bố mẹ.)","Khả năng rất nhỏ nên dùng loại 2, không dùng loại 1."],["Dùng could","If we left now, we could still catch the train.\n(Nếu giờ chúng ta đi thì vẫn có thể kịp tàu.)","Could thay would khi muốn nói về khả năng thực hiện."],["Trật tự đảo","She would travel more if she had a better job.\n(Cô ấy sẽ đi du lịch nhiều hơn nếu có công việc tốt hơn.)","Mệnh đề if đứng sau thì không cần dấu phẩy."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Loại 1 và loại 2 trên cùng tình huống"},{"table":[["Loại câu","Sắc thái","Ví dụ"],["Loại 1","có thật khả năng xảy ra","If I have time, I will call you."],["Loại 2","giả định, trái thực tế hoặc khó xảy ra","If I had time, I would call you."],["would ở mệnh đề chính","không bao giờ xuất hiện ở mệnh đề if","If I knew, I would tell you."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: If I would have more time, I would learn the piano. → Đã sửa: If I had more time, I would learn the piano. — Mệnh đề if không dùng would."},{"p":"Chưa đúng: If I was you, I would apologise. → Đã sửa: If I were you, I would apologise. — Trong cấu trúc giả định, dạng chuẩn mực là were cho mọi chủ ngữ."},{"p":"Chưa đúng: If she studied harder, she will get better marks. → Đã sửa: If she studied harder, she would get better marks. — Loại 2 dùng would ở mệnh đề chính, không dùng will."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Tình huống là giả định trái thực tế hay có thật khả năng xảy ra."},{"p":"Mệnh đề if ở quá khứ đơn và không có would."},{"p":"Mệnh đề chính dùng would, could hoặc might."},{"p":"Động từ be ở dạng were trong cấu trúc giả định."}]}],"id":"b1-16"},{"n":17,"title":"Passive voice","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Câu bị động chuyển trọng tâm từ người thực hiện sang đối tượng chịu tác động. Người ta dùng bị động khi không biết ai thực hiện, khi tác nhân không quan trọng hoặc khi muốn giữ giọng khách quan trong văn viết. Thì của câu không đổi: nó được thể hiện qua động từ be, còn động từ chính luôn ở dạng quá khứ phân từ."},{"p":"Cấu trúc chính: S + be + V3 (+ by + tác nhân)"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The bridge was built in 1998. (Không biết hoặc không cần nêu tác nhân | Nhấn mạnh đối tượng chịu tác động | Giữ giọng khách quan trong văn viết)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Không biết hoặc không cần nêu tác nhân: Bỏ hẳn cụm by khi thông tin đó không cần thiết. (My bike was stolen last night.)"},{"p":"Nhấn mạnh đối tượng chịu tác động: Đối tượng được đưa lên đầu câu để làm trọng tâm thông tin. (This temple was built in the 15th century.)"},{"p":"Giữ giọng khách quan trong văn viết: Thường gặp trong báo cáo, hướng dẫn và văn bản học thuật. (The samples were tested twice.)"},{"p":"Nêu tác nhân khi thực sự quan trọng: Dùng by khi người thực hiện là thông tin mới và đáng chú ý. (The novel was written by a teenager.)"},{"p":"Ghi nhớ: Đưa đối tượng chịu tác động lên làm chủ ngữ, dùng be chia theo thì cộng quá khứ phân từ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + be + V3 (+ by + tác nhân)"},{"table":[["Thì / Dạng","Công thức","Ví dụ"],["Hiện tại đơn","am/is/are + V3","The office is cleaned every day."],["Quá khứ đơn","was/were + V3","The letters were sent yesterday."],["Hiện tại hoàn thành","have/has been + V3","The report has been finished."],["Có động từ khuyết thiếu","động từ khuyết thiếu + be + V3","This form must be signed."],["Bị động tiếp diễn","am/is/are + being + V3 = đang được làm","The protocol is being revised after the pilot study."],["V3 bất quy tắc trong bị động","give → given, take → taken, make → made","Every student was given a certificate."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định tân ngữ của câu chủ động: Tân ngữ đó sẽ trở thành chủ ngữ của câu bị động. (They built the bridge. → The bridge…)"},{"p":"02. Chia be theo thì gốc và chủ ngữ mới: Thì không đổi, chỉ hình thức đổi. (built → was built)"},{"p":"03. Đưa động từ chính về quá khứ phân từ: Thêm cụm by + tác nhân chỉ khi thông tin đó cần thiết. (was built by the French)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Quá khứ đơn","The bridge was built in 1998.\n(Cây cầu được xây năm 1998.)","Ai xây không quan trọng nên bỏ cụm by; was thể hiện thì quá khứ, built là quá khứ phân từ."],["Hiện tại đơn","The office is cleaned every evening.\n(Văn phòng được dọn mỗi tối.)","Is thể hiện thì hiện tại đơn và hòa hợp với chủ ngữ số ít the office."],["Không biết tác nhân","My bike was stolen last night.\n(Tối qua xe đạp của tôi bị lấy mất.)","Người lấy không rõ nên câu bị động là cách diễn đạt tự nhiên nhất."],["Hiện tại hoàn thành","The report has been sent to all departments.\n(Báo cáo đã được gửi tới tất cả các phòng.)","Cấu trúc gồm has been cộng quá khứ phân từ."],["Có động từ khuyết thiếu","This form must be signed by both parents.\n(Mẫu đơn này phải được cả bố và mẹ kí.)","Sau động từ khuyết thiếu là be ở dạng nguyên mẫu, rồi đến quá khứ phân từ."],["Nêu tác nhân đáng chú ý","This novel was written by a seventeen-year-old student.\n(Quyển tiểu thuyết này do một học sinh mười bảy tuổi viết.)","Tác nhân là thông tin mới và gây chú ý nên cụm by được giữ lại."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chuyển từ chủ động sang bị động"},{"table":[["Câu chủ động","Thì","Câu bị động"],["They clean the office.","hiện tại đơn","The office is cleaned."],["They cleaned the office.","quá khứ đơn","The office was cleaned."],["They have cleaned the office.","hiện tại hoàn thành","The office has been cleaned."],["They will clean the office.","tương lai","The office will be cleaned."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The bridge was build in 1998. → Đã sửa: The bridge was built in 1998. — Sau be phải là quá khứ phân từ, không phải động từ nguyên mẫu."},{"p":"Chưa đúng: The letters were sent by yesterday. → Đã sửa: The letters were sent yesterday. — By chỉ dùng trước tác nhân, không dùng trước trạng ngữ thời gian."},{"p":"Chưa đúng: This form must is signed. → Đã sửa: This form must be signed. — Sau động từ khuyết thiếu là be ở dạng nguyên mẫu."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Tân ngữ của câu chủ động đã trở thành chủ ngữ mới."},{"p":"Động từ be chia đúng theo thì và theo chủ ngữ mới."},{"p":"Động từ chính ở dạng quá khứ phân từ."},{"p":"Cụm by chỉ xuất hiện khi tác nhân thực sự cần nêu."}]}],"id":"b1-17"},{"n":18,"title":"That- and wh- noun clauses","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mệnh đề danh ngữ là một mệnh đề đứng ở vị trí mà bình thường một danh từ đảm nhiệm. Nó mở đầu bằng that, bằng một từ hỏi hoặc bằng if và whether. Điểm dễ sai nhất là khi mệnh đề mở đầu bằng từ hỏi. Khi đó mệnh đề không còn là câu hỏi nên phải trở về trật tự chủ ngữ trước động từ và bỏ trợ động từ."},{"p":"Cấu trúc chính: S + V + that + mệnh đề | S + V + wh- + mệnh đề"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I don't know where she lives, but I think that she moved last year. (Làm tân ngữ của động từ | Mệnh đề mở đầu bằng từ hỏi | Làm chủ ngữ của câu)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Làm tân ngữ của động từ: Sau think, know, believe, say, hope, mệnh đề that thường lược bỏ that trong văn nói. (I think (that) she is right.)"},{"p":"Mệnh đề mở đầu bằng từ hỏi: Giữ trật tự câu kể, không đảo động từ và không dùng do. (I don't know where she lives.)"},{"p":"Làm chủ ngữ của câu: Mệnh đề that hoặc wh- có thể làm chủ ngữ và kéo theo động từ số ít. (What she said surprised everyone.)"},{"p":"Câu hỏi gián tiếp lịch sự: Dùng if hoặc whether khi câu hỏi gốc là dạng có hoặc không. (Could you tell me whether the shop is open?)"},{"p":"Ghi nhớ: Một mệnh đề có thể giữ vai trò như một danh từ: làm chủ ngữ, tân ngữ hoặc bổ ngữ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + V + that + mệnh đề | S + V + wh- + mệnh đề"},{"table":[["Dạng mệnh đề","Công thức","Ví dụ"],["that + mệnh đề","sau động từ chỉ nhận thức và phát ngôn; that lược được","He said (that) he was busy."],["wh- + mệnh đề","what, where, when, why, how, who + S + V","I wonder why he left."],["if / whether + mệnh đề","cho câu hỏi dạng có hoặc không","I asked whether it was free."],["Làm chủ ngữ","mệnh đề + động từ số ít","That he lied is obvious."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định vai trò của mệnh đề: Chủ ngữ, tân ngữ hay bổ ngữ; vai trò này quyết định vị trí của mệnh đề trong câu. (What he wants is unclear.)"},{"p":"02. Đưa mệnh đề wh- về trật tự câu kể: Bỏ trợ động từ do, does, did và đặt chủ ngữ trước động từ. (Where does she live? → where she lives)"},{"p":"03. Chọn từ mở đầu phù hợp: Câu hỏi có từ hỏi thì giữ từ hỏi; câu hỏi có hoặc không thì dùng if hoặc whether; mệnh đề kể thì dùng that. (whether it is open)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Hai loại mệnh đề trong một câu","I don't know where she lives, but I think that she moved last year.\n(Tôi không biết cô ấy sống ở đâu, nhưng tôi nghĩ là cô ấy chuyển đi năm ngoái.)","Mệnh đề wh- giữ trật tự she lives; mệnh đề that làm tân ngữ của think."],["Lược bỏ that","She said she would be late.\n(Cô ấy nói sẽ đến muộn.)","That thường được lược trong văn nói và văn viết thông thường."],["Làm chủ ngữ","What she said surprised everyone in the room.\n(Điều cô ấy nói làm mọi người trong phòng bất ngờ.)","Mệnh đề what she said làm chủ ngữ nên kéo theo động từ số ít surprised."],["Câu hỏi gián tiếp","Could you tell me whether the shop is open on Sundays?\n(Bạn cho tôi biết Chủ nhật cửa hàng có mở không?)","Câu hỏi gốc là dạng có hoặc không nên dùng whether, và trật tự là the shop is."],["Sau tính từ","I am sure that he will come.\n(Tôi chắc là anh ấy sẽ đến.)","Mệnh đề that cũng đứng được sau tính từ như sure, afraid, glad."],["Mệnh đề how","Nobody knows how he solved the problem so quickly.\n(Không ai biết anh ấy giải bài đó nhanh như vậy bằng cách nào.)","How mở đầu mệnh đề danh ngữ và trật tự vẫn là he solved."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Câu hỏi trực tiếp và mệnh đề danh ngữ"},{"table":[["Mẫu câu","Đặc điểm","Ví dụ / Dấu câu"],["Where does she live?","câu hỏi trực tiếp, có trợ động từ","dấu hỏi ở cuối"],["I don't know where she lives.","mệnh đề danh ngữ, trật tự câu kể","dấu chấm ở cuối"],["Is it open? → whether it is open","câu hỏi có hoặc không chuyển thành whether","I wonder whether it is open."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I don't know where does she live. → Đã sửa: I don't know where she lives. — Mệnh đề danh ngữ không còn là câu hỏi nên bỏ trợ động từ và giữ trật tự câu kể."},{"p":"Chưa đúng: Could you tell me is the shop open? → Đã sửa: Could you tell me whether the shop is open? — Câu hỏi gián tiếp dạng có hoặc không cần whether hoặc if, và trật tự câu kể."},{"p":"Chưa đúng: What she said were surprising. → Đã sửa: What she said was surprising. — Mệnh đề danh ngữ làm chủ ngữ kéo theo động từ số ít."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mệnh đề giữ vai trò chủ ngữ, tân ngữ hay bổ ngữ."},{"p":"Mệnh đề wh- ở trật tự câu kể và không có trợ động từ."},{"p":"Từ mở đầu chọn đúng giữa that, từ hỏi và whether."},{"p":"Mệnh đề làm chủ ngữ đi với động từ số ít."}]}],"id":"b1-18"},{"n":19,"title":"Defining relative clauses","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mệnh đề quan hệ xác định cung cấp thông tin cần thiết để người đọc biết đang nói về ai hoặc cái gì. Vì thông tin là cần thiết, loại mệnh đề này không dùng dấu phẩy. Đại từ quan hệ được chọn theo đối tượng được bổ nghĩa, và khi nó giữ vai trò tân ngữ trong mệnh đề thì có thể lược bỏ."},{"p":"Cấu trúc chính: danh từ + who/which/that + mệnh đề"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The man who lives next door is a doctor. (Xác định người đang nói tới | Xác định vật hoặc sự việc | Nêu quan hệ sở hữu)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Xác định người đang nói tới: Dùng who hoặc that cho người. (The woman who called you is my aunt.)"},{"p":"Xác định vật hoặc sự việc: Dùng which hoặc that cho vật và con vật. (The book which you lent me was excellent.)"},{"p":"Nêu quan hệ sở hữu: Whose dùng cho cả người và vật, luôn đi với một danh từ ngay sau. (The student whose phone rang apologised.)"},{"p":"Chỉ nơi chốn và thời gian: Where chỉ nơi chốn, when chỉ thời gian. (the town where I grew up / the day when we met)"},{"p":"Ghi nhớ: Mệnh đề bổ nghĩa cho danh từ, dùng who cho người, which cho vật, that cho cả hai."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: danh từ + who/which/that + mệnh đề"},{"table":[["Đại từ / Trạng từ","Chức năng / Quy tắc","Ví dụ"],["who / that","bổ nghĩa cho người","the man who helped us"],["which / that","bổ nghĩa cho vật, con vật","the car which broke down"],["whose","chỉ sở hữu, đi kèm một danh từ","the girl whose bag was lost"],["lược bỏ","lược được khi đại từ quan hệ làm tân ngữ","the book (that) I read"],["the reason why","the reason why + mệnh đề = lý do mà","That is the reason why he resigned."],["whom","whom thay người ở vị trí tân ngữ (trang trọng); bắt buộc sau giới từ","The statistician whom they consulted had warned them."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định danh từ cần bổ nghĩa: Mệnh đề quan hệ đứng ngay sau danh từ đó, không tách ra xa. (The man … is a doctor → The man who lives next door is a doctor.)"},{"p":"02. Chọn đại từ quan hệ theo đối tượng: Người dùng who, vật dùng which, that dùng được cho cả hai trong mệnh đề xác định. (the film that won the prize)"},{"p":"03. Xét vai trò của đại từ trong mệnh đề: Nếu sau đại từ là một động từ thì nó làm chủ ngữ và không lược được; nếu sau đại từ là một chủ ngữ khác thì nó làm tân ngữ và lược được. (the book (which) she wrote)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Bổ nghĩa cho người","The man who lives next door is a doctor.\n(Người đàn ông sống ở nhà kế bên là bác sĩ.)","Who làm chủ ngữ của lives nên không thể lược bỏ."],["Bổ nghĩa cho vật","The bus which goes to the airport leaves at six.\n(Chuyến xe buýt đi sân bay khởi hành lúc sáu giờ.)","Which bổ nghĩa cho the bus và làm chủ ngữ của goes."],["Lược bỏ đại từ","The book you lent me was excellent.\n(Quyển sách bạn cho tôi mượn rất hay.)","Đại từ quan hệ làm tân ngữ của lent nên lược bỏ được mà câu vẫn đúng."],["Chỉ sở hữu","The student whose phone rang apologised to the class.\n(Học sinh có điện thoại reo đã xin lỗi cả lớp.)","Whose luôn đi kèm một danh từ ngay sau, ở đây là phone."],["Chỉ nơi chốn","This is the village where my grandparents were born.\n(Đây là ngôi làng nơi ông bà tôi sinh ra.)","Where thay cho cụm in which nên sau nó không cần giới từ."],["Dùng that","The film that won the award is showing tonight.\n(Bộ phim đoạt giải đang chiếu tối nay.)","Trong mệnh đề xác định, that thay được cho cả who và which."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Khi nào lược được đại từ quan hệ"},{"table":[["Vai trò","Quy tắc","Ví dụ"],["làm chủ ngữ","không lược được","the man who called me"],["làm tân ngữ","lược được","the man (who) I called"],["whose","không lược được","the man whose car broke down"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The man which lives next door is a doctor. → Đã sửa: The man who lives next door is a doctor. — Which không dùng cho người."},{"p":"Chưa đúng: The book that I read it was interesting. → Đã sửa: The book that I read was interesting. — Đại từ quan hệ đã thay cho tân ngữ nên không lặp lại it."},{"p":"Chưa đúng: The girl, who sits next to me, is from Hue. → Đã sửa: The girl who sits next to me is from Hue. — Mệnh đề xác định nêu thông tin cần thiết nên không dùng dấu phẩy."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Đại từ quan hệ chọn đúng theo người hoặc vật."},{"p":"Mệnh đề quan hệ đứng ngay sau danh từ được bổ nghĩa."},{"p":"Không lặp lại tân ngữ trong mệnh đề quan hệ."},{"p":"Mệnh đề xác định không dùng dấu phẩy."}]}],"id":"b1-19"},{"n":20,"title":"Relative clauses with prepositions","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi động từ trong mệnh đề quan hệ đòi hỏi một giới từ, giới từ đó không được bỏ đi. Có hai cách đặt nó: để ở cuối mệnh đề, cách thông dụng trong văn nói và văn viết bình thường; hoặc đưa lên trước đại từ quan hệ, cách trang trọng và chỉ dùng được với whom và which. Khi giới từ đứng trước thì không được dùng that và không được lược đại từ."},{"p":"Cấu trúc chính: the person (who) I spoke to | the person to whom I spoke"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): This is the colleague I work with. (Văn nói và văn viết thông thường | Văn viết trang trọng | Nêu số lượng trong một nhóm)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Văn nói và văn viết thông thường: Giới từ đứng cuối mệnh đề; đại từ quan hệ thường được lược. (the house we lived in)"},{"p":"Văn viết trang trọng: Giới từ đứng trước whom cho người và which cho vật. (the house in which we lived)"},{"p":"Nêu số lượng trong một nhóm: Dùng cụm some of whom, many of which sau dấu phẩy. (the guests, some of whom I knew)"},{"p":"Chỉ thời gian, nơi chốn, lí do: Where, when và why thay cho cụm giới từ cộng which. (the day when we met = the day on which we met)"},{"p":"Ghi nhớ: Giới từ có thể đứng ở cuối mệnh đề trong văn nói hoặc đứng trước whom và which trong văn viết trang trọng."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: the person (who) I spoke to | the person to whom I spoke"},{"table":[["Vị trí / Dạng","Công thức / Quy tắc","Ví dụ"],["Giới từ ở cuối","danh từ + (that/who/which) + S + V + giới từ","the person I talked to"],["Giới từ ở trước","danh từ + giới từ + whom/which + S + V","the person to whom I talked"],["Không dùng that","sai: the person to that I talked","to whom, không phải to that"],["Thay bằng trạng từ quan hệ","in which → where | on which → when | for which → why","the room where we met"],["from/at + which","giới từ nào của động từ thì giữ nguyên trước which: from which, at which, in which…","the layer from which the sample was taken / the rate at which the ice is thinning"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Tìm giới từ mà động từ đòi hỏi: Work with, talk to, look after, depend on đều cần giới từ đi kèm. (work with → the colleague I work with)"},{"p":"02. Chọn vị trí cho giới từ: Cuối mệnh đề cho văn phong thông thường; trước đại từ quan hệ cho văn phong trang trọng. (the man I spoke to ↔ the man to whom I spoke)"},{"p":"03. Kiểm tra đại từ sau giới từ: Chỉ dùng whom và which, không dùng that, và không được lược bỏ. (the project on which we worked)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Giới từ ở cuối","This is the colleague I work with.\n(Đây là người đồng nghiệp tôi làm việc cùng.)","Giới từ with không được bỏ; đại từ quan hệ ở vị trí tân ngữ nên lược được."],["Văn phong trang trọng","This is the colleague with whom I work.\n(Đây là người đồng nghiệp tôi làm việc cùng.)","Cùng nội dung nhưng giới từ đưa lên trước whom, giọng trang trọng hơn."],["Bổ nghĩa cho vật","The project which we worked on lasted two years.\n(Dự án chúng tôi làm kéo dài hai năm.)","Giới từ on đứng ở cuối mệnh đề quan hệ, trước động từ của mệnh đề chính."],["Dạng trang trọng với which","The project on which we worked lasted two years.\n(Dự án mà chúng tôi làm kéo dài hai năm.)","On which là dạng trang trọng; không viết on that."],["Nêu số lượng trong nhóm","There were twenty guests, some of whom I had never met.\n(Có hai mươi khách, trong đó có mấy người tôi chưa gặp bao giờ.)","Sau giới từ of thì dùng whom cho người."],["Thay bằng trạng từ quan hệ","I still remember the room where we first met.\n(Tôi vẫn nhớ căn phòng nơi chúng tôi gặp nhau lần đầu.)","Where thay cho cụm in which, nên sau nó không cần giới từ nữa."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai cách đặt giới từ"},{"table":[["Vị trí","Đặc điểm","Ví dụ"],["giới từ ở cuối","thông dụng, lược được đại từ","the film we talked about"],["giới từ ở trước","trang trọng, dùng whom hoặc which","the film about which we talked"],["trạng từ quan hệ","gọn nhất khi nói về nơi chốn, thời gian, lí do","the place where we talked"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: This is the colleague I work. → Đã sửa: This is the colleague I work with. — Động từ work đòi hỏi giới từ with và giới từ đó không được bỏ."},{"p":"Chưa đúng: The project on that we worked lasted two years. → Đã sửa: The project on which we worked lasted two years. — Khi giới từ đứng trước thì chỉ dùng which hoặc whom, không dùng that."},{"p":"Chưa đúng: I remember the room where we met in. → Đã sửa: I remember the room where we met. — Where đã bao hàm giới từ in nên không thêm giới từ nữa."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Giới từ mà động từ đòi hỏi không bị bỏ sót."},{"p":"Khi giới từ đứng trước thì dùng whom hoặc which."},{"p":"Khi giới từ đứng trước thì không lược đại từ quan hệ."},{"p":"Where, when và why đã bao hàm giới từ nên không thêm nữa."}]}],"id":"b1-20"},{"n":21,"title":"Agreement & tag questions","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Câu hỏi đuôi là phần ngắn thêm vào cuối câu để xác nhận thông tin hoặc mời người nghe đồng tình. Nó được tạo từ ba nguyên tắc: lấy đúng trợ động từ của mệnh đề chính, đảo dấu khẳng định và phủ định, rồi dùng đại từ tương ứng với chủ ngữ. Nắm sự hòa hợp chủ ngữ với động từ là điều kiện để làm đúng phần đuôi."},{"p":"Cấu trúc chính: mệnh đề khẳng định + trợ động từ phủ định + đại từ?"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She works here, doesn't she? (Xác nhận điều mình cho là đúng | Xác nhận điều phủ định | Mời đồng tình trong hội thoại)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Xác nhận điều mình cho là đúng: Mệnh đề khẳng định đi với đuôi phủ định. (You're from Hue, aren't you?)"},{"p":"Xác nhận điều phủ định: Mệnh đề phủ định đi với đuôi khẳng định. (She doesn't drive, does she?)"},{"p":"Mời đồng tình trong hội thoại: Ngữ điệu xuống thể hiện người nói đã chắc và chỉ mong người nghe đồng ý. (It's a lovely day, isn't it?)"},{"p":"Hòa hợp với chủ ngữ phức: Chủ ngữ có cụm bổ nghĩa dài vẫn quyết định dạng động từ theo danh từ chính. (The list of names is on the desk, isn't it?)"},{"p":"Ghi nhớ: Câu hỏi đuôi lấy trợ động từ của mệnh đề chính và đảo dấu khẳng định hoặc phủ định."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: mệnh đề khẳng định + trợ động từ phủ định + đại từ?"},{"table":[["Trường hợp","Quy tắc / Dạng đặc biệt","Ví dụ"],["Có trợ động từ","lặp lại trợ động từ đó","They have left, haven't they?"],["Không có trợ động từ","dùng do/does/did","He plays tennis, doesn't he?"],["Động từ to be","lặp lại be","You are ready, aren't you?"],["Trường hợp đặc biệt","I am → aren't I | Let's → shall we | mệnh lệnh → will you","Let's go, shall we?"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Tìm trợ động từ của mệnh đề chính: Nếu không có trợ động từ thì dùng do, does hoặc did theo thì và chủ ngữ. (She works → doesn't she)"},{"p":"02. Đảo dấu khẳng định và phủ định: Mệnh đề khẳng định thì đuôi phủ định và ngược lại. (He is here, isn't he? ↔ He isn't here, is he?)"},{"p":"03. Chọn đại từ khớp với chủ ngữ: Danh từ chính của chủ ngữ quyết định đại từ, kể cả khi chủ ngữ có cụm bổ nghĩa dài. (The books on the shelf are new, aren't they?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Khẳng định với đuôi phủ định","She works here, doesn't she?\n(Cô ấy làm ở đây, phải không?)","Mệnh đề chính không có trợ động từ nên phần đuôi dùng does; đại từ she khớp với chủ ngữ."],["Phủ định với đuôi khẳng định","They haven't arrived yet, have they?\n(Họ vẫn chưa đến, phải không?)","Mệnh đề chính phủ định nên phần đuôi ở dạng khẳng định have."],["Với động từ to be","You are from Hue, aren't you?\n(Bạn là người Huế, đúng không?)","To be tự làm trợ động từ nên phần đuôi lặp lại chính nó."],["Chủ ngữ có cụm bổ nghĩa","The list of names is on your desk, isn't it?\n(Danh sách tên nằm trên bàn bạn, phải không?)","Danh từ chính là list ở số ít, nên động từ là is và đại từ là it."],["Trường hợp I am","I'm late, aren't I?\n(Tôi đến muộn, phải không?)","Tiếng Anh không có dạng amn't, nên phần đuôi của I am là aren't I."],["Với Let's và mệnh lệnh","Let's take a break, shall we? And close the door, will you?\n(Nghỉ một chút nhé? Và đóng cửa giúp tôi nhé?)","Let's đi với shall we, câu mệnh lệnh đi với will you."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba bước tạo câu hỏi đuôi"},{"table":[["Thành phần","Quy tắc","Ví dụ"],["trợ động từ","lấy từ mệnh đề chính hoặc dùng do/does/did","He can swim, can't he?"],["dấu","đảo khẳng định thành phủ định và ngược lại","She isn't here, is she?"],["đại từ","khớp với danh từ chính của chủ ngữ","Your sister called, didn't she?"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She works here, doesn't it? → Đã sửa: She works here, doesn't she? — Đại từ trong phần đuôi phải khớp với chủ ngữ của mệnh đề chính."},{"p":"Chưa đúng: They haven't arrived, haven't they? → Đã sửa: They haven't arrived, have they? — Mệnh đề phủ định phải đi với phần đuôi khẳng định."},{"p":"Chưa đúng: I'm late, amn't I? → Đã sửa: I'm late, aren't I? — Tiếng Anh không có dạng amn't; phần đuôi của I am là aren't I."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Trợ động từ trong phần đuôi lấy đúng từ mệnh đề chính."},{"p":"Dấu khẳng định và phủ định đã được đảo."},{"p":"Đại từ khớp với danh từ chính của chủ ngữ."},{"p":"Các trường hợp đặc biệt như aren't I, shall we, will you dùng đúng."},{"p":"Câu hỏi đuôi mượn đúng trợ động từ theo mệnh đề chính: has, was, do hoặc did."}]}],"id":"b1-21"}];
